"use client";
/* eslint-disable @typescript-eslint/no-explicit-any */

import { useEffect, useMemo, useState, type ComponentType } from "react";
import {
  AreaChart, Area, BarChart as ReBarChart, Bar, CartesianGrid, Cell, Pie, PieChart,
  ResponsiveContainer, Tooltip, XAxis, YAxis,
} from "recharts";
import {
  ArrowDownLeft, ArrowRight, ArrowUpRight, Bell, CalendarDays, Check,
  ChevronDown, ChevronRight, CircleDollarSign, CreditCard, Download, Eye,
  EyeOff, Flag, Heart, Home, Landmark, LayoutDashboard, Lightbulb, Menu,
  MessageCircleHeart, Moon, MoreHorizontal, Plus, ReceiptText, Search,
  Settings, Sparkles, Sun, Target, TrendingDown, TrendingUp, Users, WalletCards,
  X, Zap,
} from "lucide-react";
import { AuthGate } from "@/components/auth-gate";
import { CloudSync } from "@/components/cloud-sync";
import { useAuth } from "@/lib/auth-context";

const brl = (value: number) => new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(value);
const appAction = (detail: string | { page: string }) => window.dispatchEvent(new CustomEvent('juntos-action', { detail }));
const ZERO_DATA_VERSION_KEY = 'juntos-reset-version';
const ZERO_DATA_VERSION = 'zero-financial-data-v3';
const displayPerson=(people:any,key:string)=>key==='Rafael'?people.Rafael.name.split(' ')[0]:key==='Mariana'?people.Mariana.name.split(' ')[0]:key;
const displayTitle=(people:any,title:string)=>title==='Salário Rafael'?'Salário '+people.Rafael.name.split(' ')[0]:title;

const menu = [
  ["Dashboard", LayoutDashboard], ["Transações", ReceiptText], ["Orçamentos", CircleDollarSign], ["Contas", Landmark],
  ["Cartões", CreditCard], ["Calendário", CalendarDays], ["Metas", Target],
  ["Assinaturas", Zap], ["Despesas fixas", ReceiptText], ["App de compras", Search],
  ["Empréstimos", Landmark], ["Cuidados pessoais", Heart],
  ["Relatórios", TrendingUp], ["Linha do tempo", CalendarDays], ["IA Conselheira", MessageCircleHeart],
] as const;

const transactions: any[] = [];

const goals: any[] = [];

const expenses: any[] = [];
const cashflow: any[] = [];

function Avatar({ who, small = false, label }: { who: "R" | "M"; small?: boolean; label?: string }) {
  return <div className={`avatar ${small ? "small" : ""} ${who === "M" ? "mariana" : "rafael"}`}>{(label||who).trim().charAt(0).toUpperCase()}</div>;
}

function Logo() {
  return <div className="logo"><span><Heart size={17} fill="currentColor" /></span><div>Juntos <b>Finance</b></div></div>;
}

function MetricCard({ label, value, detail, icon: Icon, tone = "default", hide = false }: { label: string; value: string; detail: string; icon: ComponentType<{size?: number}>; tone?: string; hide?: boolean }) {
  return <article className={`metric card ${tone}`}>
    <div className="metric-head"><span>{label}</span><i><Icon size={18} /></i></div>
    <strong>{hide ? "••••••" : value}</strong>
    <small>{detail}</small>
  </article>;
}

function Dashboard({ onNew, onAi, hidden, setHidden, people, balances, currentName, isCouple }: { onNew: () => void; onAi: () => void; hidden: boolean; setHidden: (value: boolean) => void; people:any; balances:any; currentName?:string; isCouple:boolean }) {
  const [period,setPeriod]=useState('2026-07');
  const [dashboardItems,setDashboardItems]=useState<any[]>([]);
  useEffect(()=>{const loadTransactions=()=>{const saved=localStorage.getItem('juntos-transactions');setDashboardItems(saved?JSON.parse(saved):transactions)};loadTransactions();window.addEventListener('juntos-transactions-updated',loadTransactions);return()=>window.removeEventListener('juntos-transactions-updated',loadTransactions)},[]);
  const periodItems=dashboardItems.filter(item=>!item.dateInput||item.dateInput.startsWith(period));
  const monthIncome=periodItems.filter(item=>item.type==='in').reduce((total,item)=>total+Number(item.value||0),0);
  const monthExpense=periodItems.filter(item=>item.type==='out').reduce((total,item)=>total+Number(item.value||0),0);
  const monthSavings=monthIncome-monthExpense;
  const chartColors=['#7f2854','#b76a8e','#d79ab6','#8f6bb2','#d39155','#4c8d7b','#6d7f9f'];
  const categoryTotals=Object.entries(periodItems.filter(item=>item.type==='out').reduce((groups:Record<string,number>,item:any)=>{groups[item.category||'Outros']=(groups[item.category||'Outros']||0)+Number(item.value||0);return groups},{})).sort((a,b)=>b[1]-a[1]);
  const categoryExpenses=categoryTotals.map(([name,value],index)=>({name,value,percentage:monthExpense?Math.round(value/monthExpense*100):0,color:chartColors[index%chartColors.length]}));
  const dashboardCashflow=Array.from({length:6},(_,offset)=>{const [year,month]=period.split('-').map(Number);const date=new Date(year,month-1-(5-offset),1);const key=date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0');const items=dashboardItems.filter(item=>item.dateInput?.startsWith(key));return {m:new Intl.DateTimeFormat('pt-BR',{month:'short'}).format(date).replace('.',''),receita:items.filter(item=>item.type==='in').reduce((sum,item)=>sum+Number(item.value||0),0),despesa:items.filter(item=>item.type==='out').reduce((sum,item)=>sum+Number(item.value||0),0)}});
  const [salary,setSalary]=useState(0);
  const [salaryItems,setSalaryItems]=useState<any[]>([]);
  const [salaryOpen,setSalaryOpen]=useState(false);
  const [salaryEditing,setSalaryEditing]=useState<any|null>(null);
  useEffect(()=>{const loadSalary=()=>{const saved=localStorage.getItem('juntos-transactions');const items=saved?JSON.parse(saved):transactions;const salaries=items.filter((item:any)=>item.type==='in'&&item.category==='Salário'&&(item.person==='Rafael'||(isCouple&&item.person==='Casal')));setSalaryItems(salaries);setSalary(salaries.reduce((total:number,item:any)=>total+Number(item.value||0),0))};loadSalary();window.addEventListener('juntos-transactions-updated',loadSalary);return()=>window.removeEventListener('juntos-transactions-updated',loadSalary)},[isCouple]);
  const openNewSalary=()=>setSalaryEditing({id:null,value:'',dateInput:new Date().toISOString().slice(0,10),person:'Rafael'});
  const saveSalary=(event:React.FormEvent)=>{event.preventDefault();const value=Number(String(salaryEditing.value).replace(/[.]/g,'').replace(',','.'));if(!value||value<=0)return;const saved=localStorage.getItem('juntos-transactions');const all=saved?JSON.parse(saved):transactions;const dateInput=salaryEditing.dateInput||new Date().toISOString().slice(0,10);const date=new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(dateInput+'T12:00:00')).replace('.','');const record={...salaryEditing,id:salaryEditing.id||Date.now(),title:'Salário',category:'Salário',account:salaryEditing.person==='Casal'?'Conta do casal':'Conta Rafael',type:'in',icon:'↗',value,date,dateInput};const next=salaryEditing.id?all.map((item:any)=>item.id===record.id?record:item):[record,...all];localStorage.setItem('juntos-transactions',JSON.stringify(next));window.dispatchEvent(new Event('juntos-transactions-updated'));setSalaryEditing(null);appAction(salaryEditing.id?'Salário atualizado.':'Salário cadastrado.')};
  const deleteSalary=(id:number)=>{if(!confirm('Deseja excluir este salário?'))return;const saved=localStorage.getItem('juntos-transactions');const all=saved?JSON.parse(saved):transactions;localStorage.setItem('juntos-transactions',JSON.stringify(all.filter((item:any)=>item.id!==id)));window.dispatchEvent(new Event('juntos-transactions-updated'));setSalaryEditing(null);appAction('Salário excluído.')};
  const periodOptions=Array.from({length:36},(_,i)=>{const date=new Date(2025+Math.floor(i/12),i%12,1);return {value:date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0'),label:new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(date).replace(/^./,x=>x.toUpperCase())}});
  return <>
    <section className="welcome">
      <div><p>Domingo, 19 de julho</p><h1>Olá, {(currentName||people.Rafael.name).trim().split(' ')[0]} <span>👋</span></h1><small>Seu dinheiro, seus planos, uma vida juntos.</small></div>
      <div className="welcome-actions">
        <label className="ghost period period-picker"><CalendarDays size={17}/><span>{periodOptions.find(x=>x.value===period)?.label}</span><ChevronDown size={16}/><select value={period} onChange={e=>setPeriod(e.target.value)} aria-label="Selecionar mês e ano">{periodOptions.map(x=><option value={x.value} key={x.value}>{x.label}</option>)}</select></label>
        <button className="primary" onClick={onNew}><Plus size={18} /> Nova transação</button>
      </div>
    </section>

    <div className="balance-hero">
      <div className="balance-copy">
        <div className="eyebrow">Total de sal?rios <button className="icon-button invert" onClick={() => setHidden(!hidden)} aria-label="Mostrar ou ocultar saldo">{hidden ? <EyeOff size={17}/> : <Eye size={17}/>}</button></div>
        <h2>{hidden ? "R$ ••••••" : brl(salary)}</h2>
        <span className="up"><TrendingUp size={15}/> Sem movimentações registradas</span>
      </div>
      <div className="couple-balances">
        <button className="personal-balance" onClick={()=>{setSalaryOpen(true);setSalaryEditing(null)}} title="Gerenciar sal?rios"><Avatar who="R" small label={currentName||people.Rafael.name}/><span>{(currentName||people.Rafael.name).trim().split(' ')[0]}</span><b>{hidden ? "••••" : brl(salary)}</b></button>
      </div>
      <div className="hero-glow glow-one"/><div className="hero-glow glow-two"/>
    </div>

    <div className="metrics-grid">
      <MetricCard label="Receitas do mês" value={brl(0)} detail="Nenhuma receita cadastrada" icon={ArrowDownLeft} tone="positive" hide={hidden}/>
      <MetricCard label="Gastos do mês" value={brl(0)} detail="Nenhuma despesa cadastrada" icon={ArrowUpRight} tone="negative" hide={hidden}/>
      <MetricCard label="Economia do mês" value={brl(0)} detail="Sem dados no período" icon={CircleDollarSign} tone="purple" hide={hidden}/>
      <MetricCard label="Saldo do m?s" value={brl(Math.max(0,monthSavings))} detail="Defina um orçamento" icon={WalletCards} tone="warning" hide={hidden}/>
    </div>

    <div className="content-grid charts-row">
      <section className="card chart-card wide cashflow-bars">
        <div className="section-title"><div><h3>Receitas vs Despesas</h3></div></div>
        <div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><ReBarChart data={dashboardCashflow} margin={{top:12,right:8,left:8,bottom:0}} barGap={5} barCategoryGap="16%"><CartesianGrid vertical={false} stroke="#eee7eb"/><XAxis dataKey="m" axisLine={false} tickLine={false} tick={{fill:'#6f686c',fontSize:11}}/><YAxis hide/><Tooltip cursor={{fill:'rgba(112,34,68,.04)'}} formatter={(v,name)=>[brl(Number(v)),name==='receita'?'Receita':'Despesa']}/><Bar dataKey="receita" name="Receita" fill="#2f9961" radius={[6,6,0,0]} maxBarSize={72}/><Bar dataKey="despesa" name="Despesa" fill="#8b263f" radius={[6,6,0,0]} maxBarSize={72}/></ReBarChart></ResponsiveContainer></div>
        <div className="legend bar-legend"><span><i className="expense-bar"/>Despesa</span><span><i className="income-bar"/>Receita</span></div>
      </section>
      <section className="card chart-card donut-card">
        <div className="section-title"><div><h3>Gastos por categoria</h3><p>{periodOptions.find(option=>option.value===period)?.label}</p></div><button className="icon-button" onClick={()=>appAction({page:'Transações'})} aria-label="Ver gastos por categoria"><MoreHorizontal size={19}/></button></div>
        <div className="donut-wrap"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={categoryExpenses} dataKey="value" innerRadius={54} outerRadius={78} paddingAngle={3} startAngle={90} endAngle={-270}>{categoryExpenses.map((x)=><Cell key={x.name} fill={x.color}/>)}</Pie><Tooltip formatter={(value)=>brl(Number(value))}/></PieChart></ResponsiveContainer><div className="donut-label"><b>{brl(monthExpense)}</b><small>Total gasto</small></div></div>
        <div className="expense-legend">{categoryExpenses.map(x=><div key={x.name}><span><i style={{background:x.color}}/>{x.name}</span><b>{x.percentage}%</b></div>)}</div>
      </section>
    </div>

    <div className="content-grid lower-row">
      <section className="card transactions-card">
        <div className="section-title"><div><h3>Movimentações recentes</h3><p>Suas últimas transações</p></div><button className="text-button" onClick={()=>appAction({page:'Transações'})}>Ver todas <ArrowRight size={15}/></button></div>
        <div className="transaction-list">{dashboardItems.length?dashboardItems.slice(0,5).map(t=><div className="transaction" key={t.id}><div className={`transaction-icon ${t.type}`}>{t.icon}</div><div className="transaction-name"><b>{displayTitle(people,t.title)}</b><span>{t.category} · {displayPerson(people,t.person)}</span></div><div className="transaction-date">{t.date}</div><strong className={t.type}>{t.type === "in" ? "+" : "−"} {brl(t.value)}</strong></div>):<div className="organizer-empty">Nenhuma transação cadastrada.</div>}</div>
      </section>
      <aside className="side-stack">
        <section className="card ai-alerts-card"><div className="ai-alerts-head"><div><h3>Alertas da IA <span>0</span></h3><button onClick={onAi}>IA Conselheira <ChevronRight size={14}/></button></div></div><div className="ai-alert-list"><article><i className="alert-green"><Lightbulb size={18}/></i><div><b>Nenhum alerta por enquanto</b><p>Cadastre transações, contas e metas para receber análises.</p></div></article></div></section>
        <section className="card upcoming"><div className="section-title"><div><h3>Próximos pagamentos</h3><p>Nenhum compromisso cadastrado</p></div></div><p className="agenda-empty">Adicione eventos no calendário para acompanhar vencimentos.</p></section>
      </aside>
    </div>

    <section className="goals-section"><div className="section-title"><div><h3>Minhas metas</h3><p>Transformando planos em conquistas</p></div><button className="text-button" onClick={()=>appAction({page:"Metas"})}>Ver todas <ArrowRight size={15}/></button></div><div className="goals-grid">{goals.length?goals.map(g=>{const pct=Math.round(g.current/g.total*100);return <article className="card goal" key={g.title}><div className="goal-top"><i>{g.emoji}</i><span><b>{g.title}</b><small>Meta para {g.date}</small></span><strong>{pct}%</strong></div><div className="progress"><span style={{width:`${pct}%`,background:g.color}}/></div><div className="goal-values"><b>{hidden ? "••••" : brl(g.current)}</b><span>de {hidden ? "••••" : brl(g.total)}</span></div></article>}):<div className="organizer-empty">Nenhuma meta cadastrada.</div>}</div></section>

    {salaryOpen&&<div className="modal-backdrop" onMouseDown={event=>event.target===event.currentTarget&&setSalaryOpen(false)}><section className="modal salary-manager"><div className="edit-modal-head"><div><span>MEUS RECEBIMENTOS</span><h2>Gerenciar sal?rios</h2><p>Cadastre, edite ou exclua somente seus sal?rios.</p></div><button type="button" className="icon-button" onClick={()=>setSalaryOpen(false)}><X/></button></div>{salaryEditing?<form className="salary-form" onSubmit={saveSalary}><label>Valor do sal?rio<input value={salaryEditing.value} onChange={event=>setSalaryEditing({...salaryEditing,value:event.target.value.replace(/[^0-9,.]/g,'')})} placeholder="0,00" inputMode="decimal" required/></label><label>Data do recebimento<input type="date" value={salaryEditing.dateInput} onChange={event=>setSalaryEditing({...salaryEditing,dateInput:event.target.value})} required/></label>{isCouple&&<label>Destino<select value={salaryEditing.person} onChange={event=>setSalaryEditing({...salaryEditing,person:event.target.value})}><option value="Rafael">Meu sal?rio</option><option value="Casal">Sal?rio do casal</option></select></label>}<div className="edit-modal-actions">{salaryEditing.id&&<button type="button" className="ghost danger" onClick={()=>deleteSalary(salaryEditing.id)}>Excluir</button>}<span/><button type="button" className="ghost" onClick={()=>setSalaryEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar sal?rio</button></div></form>:<><div className="salary-manager-actions"><button className="primary" onClick={openNewSalary}><Plus size={17}/> Cadastrar sal?rio</button></div><div className="salary-list">{salaryItems.length?salaryItems.map(item=><button key={item.id} onClick={()=>setSalaryEditing({...item,value:String(item.value).replace('.',','),dateInput:item.dateInput||new Date().toISOString().slice(0,10)})}><span><b>{item.person==='Casal'?'Sal?rio do casal':'Meu sal?rio'}</b><small>{item.date}</small></span><strong>{brl(item.value)}</strong><ChevronRight size={17}/></button>):<div className="organizer-empty">Nenhum sal?rio cadastrado.</div>}</div></>}</section></div>}
  </>;
}

function TransactionsPage({ onNew, people, isCouple }: { onNew: () => void; people:any; isCouple:boolean }) {
  const [query,setQuery]=useState(''); const [person,setPerson]=useState('Todas'); const [period,setPeriod]=useState('2026-07'); const [openMenu,setOpenMenu]=useState<number|null>(null); const [editing,setEditing]=useState<any|null>(null); const [editForm,setEditForm]=useState<any>({});
  const [items,setItems]=useState<any[]>(transactions);
  const categories=['Salário','Alimentação','Mercado','Restaurante','Delivery','Transporte','Combustível','Aluguel','Condomínio','Internet','Luz','Água','Telefone','Saúde','Educação','Filhos','Viagens','Lazer','Compras','Assinaturas','Investimentos','Dívidas','Seguros','Impostos','Outros'];
  useEffect(()=>{const load=()=>{const saved=localStorage.getItem('juntos-transactions');setItems(saved?JSON.parse(saved):transactions)};load();window.addEventListener('juntos-transactions-updated',load);return()=>window.removeEventListener('juntos-transactions-updated',load)},[]);
  const persist=(next:any[])=>{setItems(next);localStorage.setItem('juntos-transactions',JSON.stringify(next));window.dispatchEvent(new Event('juntos-transactions-updated'))};
  const openEdit=(t:any)=>{setEditing(t);setEditForm({...t,value:String(t.value).replace('.',','),dateInput:t.date?.includes('-')?t.date:'2026-07-'+String(t.date).replace(/\D/g,'').padStart(2,'0')});setOpenMenu(null)};
  const saveEdit=(e:React.FormEvent)=>{e.preventDefault();const value=Number(String(editForm.value).replace(/[.]/g,'').replace(',','.'));if(!editForm.title?.trim()||Number.isNaN(value))return;persist(items.map(x=>x.id===editing.id?{...x,...editForm,title:editForm.title.trim(),value,date:editForm.dateInput?new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(editForm.dateInput+'T12:00:00')).replace('.',''):x.date}:x));setEditing(null);appAction('Transação atualizada com sucesso.')};
  const remove=(t:any)=>{if(confirm(`Excluir “${t.title}”?`)){persist(items.filter(x=>x.id!==t.id));setOpenMenu(null);appAction('Transação excluída.')}};
  const filtered=items.filter(t=>(t.title.toLowerCase().includes(query.toLowerCase())||t.category.toLowerCase().includes(query.toLowerCase()))&&(person==='Todas'||t.person===person));
  const income=items.filter(t=>t.type==='in').reduce((sum,t)=>sum+Number(t.value),0); const expense=items.filter(t=>t.type==='out').reduce((sum,t)=>sum+Number(t.value),0); const result=income-expense;
  return <div className="page-stack"><div className="page-heading"><div><p>Controle financeiro</p><h1>Transações</h1><span>Acompanhe tudo que entra e sai.</span></div><button className="primary" onClick={onNew}><Plus size={18}/> Nova transação</button></div><div className="metrics-grid compact"><MetricCard label="Entradas" value={brl(income)} detail="Este mês" icon={TrendingUp} tone="positive"/><MetricCard label="Saídas" value={brl(expense)} detail="Este mês" icon={TrendingDown} tone="negative"/><MetricCard label="Resultado" value={brl(result)} detail={result>=0?'Positivo':'Negativo'} icon={WalletCards} tone="purple"/></div><section className="card table-card"><div className="toolbar"><label className="search"><Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar transação..."/></label><select className="ghost toolbar-select" value={person} onChange={e=>setPerson(e.target.value)}><option>Todas</option><option value="Rafael">{people.Rafael.name.split(' ')[0]||'Você'}</option>{isCouple&&<><option value="Mariana">{people.Mariana.name.split(' ')[0]||'Cônjuge'}</option><option>Casal</option></>}</select><input className="ghost toolbar-month" type="month" value={period} onChange={e=>setPeriod(e.target.value)}/></div><div className="transaction-list large">{filtered.map(t=><div className="transaction" key={t.id}><div className={`transaction-icon ${t.type}`}>{t.icon}</div><div className="transaction-name"><b>{displayTitle(people,t.title)}</b><span>{t.category}</span></div><span className="person-pill">{displayPerson(people,t.person)}</span><div className="transaction-date">{t.date}</div><strong className={t.type}>{t.type === 'in' ? '+' : '−'} {brl(t.value)}</strong><div className="row-actions"><button className="icon-button" onClick={()=>setOpenMenu(openMenu===t.id?null:t.id)} aria-label="Opções da transação"><MoreHorizontal size={17}/></button>{openMenu===t.id&&<div className="row-menu"><button onClick={()=>openEdit(t)}>Editar</button><button className="danger" onClick={()=>remove(t)}>Excluir</button></div>}</div></div>)}</div></section>
    {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal edit-transaction-modal" onSubmit={saveEdit}><div className="edit-modal-head"><div><span>EDITAR MOVIMENTAÇÃO</span><h2>Editar transação</h2><p>Atualize os dados do lançamento selecionado.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X size={19}/></button></div><div className="type-switch edit-types"><button type="button" className={editForm.type==='in'?'active':''} onClick={()=>setEditForm({...editForm,type:'in',icon:'↗'})}>Receita</button><button type="button" className={editForm.type==='out'?'active':''} onClick={()=>setEditForm({...editForm,type:'out',icon:'−'})}>Despesa</button></div><div className="edit-form-grid"><label className="field-full">Descrição<input value={editForm.title||''} onChange={e=>setEditForm({...editForm,title:e.target.value})} required/></label><label>Valor (R$)<input value={editForm.value||''} onChange={e=>setEditForm({...editForm,value:e.target.value.replace(/[^0-9,.]/g,'')})} inputMode="decimal" required/></label><label>Data<input type="date" value={editForm.dateInput||''} onChange={e=>setEditForm({...editForm,dateInput:e.target.value})}/></label><label>Categoria<select value={editForm.category||''} onChange={e=>setEditForm({...editForm,category:e.target.value})}>{categories.map(x=><option key={x}>{x}</option>)}</select></label><label>Pessoa<select value={editForm.person||'Rafael'} onChange={e=>setEditForm({...editForm,person:e.target.value})}><option value="Rafael">{people.Rafael.name.split(' ')[0]||'Você'}</option>{isCouple&&<><option value="Mariana">{people.Mariana.name.split(' ')[0]||'Cônjuge'}</option><option>Casal</option></>}</select></label></div><div className="edit-modal-actions"><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar alterações</button></div></form></div>}
  </div>;
}

function BudgetsPage(){
  const initial:any[]=[];
  const [items,setItems]=useState<any[]>(initial); const [editing,setEditing]=useState<any|null>(null); const [tx,setTx]=useState<any[]>(transactions); const [period,setPeriod]=useState('2026-07');
  const categories=['Moradia','Alimentação','Mercado','Restaurante','Delivery','Transporte','Combustível','Aluguel','Condomínio','Internet','Luz','Água','Telefone','Saúde','Educação','Filhos','Viagens','Lazer','Compras','Assinaturas','Investimentos','Dívidas','Seguros','Impostos','Outros'];
  useEffect(()=>{const saved=localStorage.getItem('juntos-budgets');if(saved)setItems(JSON.parse(saved));const load=()=>{const data=localStorage.getItem('juntos-transactions');setTx(data?JSON.parse(data):transactions)};load();window.addEventListener('juntos-transactions-updated',load);return()=>window.removeEventListener('juntos-transactions-updated',load)},[]);
  const persist=(next:any[])=>{setItems(next);localStorage.setItem('juntos-budgets',JSON.stringify(next))}; const spent=(b:any)=>tx.filter(t=>t.type==='out'&&(t.category===b.category||(b.theme==='fixed'&&['Aluguel','Condomínio','Internet','Luz','Água','Telefone'].includes(t.category)))).reduce((s,t)=>s+Number(t.value),0);
  const openNew=()=>setEditing({id:Date.now(),name:'',category:'Lazer',limit:'',theme:'leisure',icon:'🎯',color:'#7c3aed',isNew:true}); const save=(e:React.FormEvent)=>{e.preventDefault();const item={...editing,limit:Number(String(editing.limit).replace(/[.]/g,'').replace(',','.'))};delete item.isNew;if(!item.name.trim()||item.limit<=0)return;persist(editing.isNew?[...items,item]:items.map(x=>x.id===item.id?item:x));setEditing(null);appAction(editing.isNew?'Orçamento criado com sucesso.':'Orçamento atualizado com sucesso.')}; const remove=()=>{if(editing&&!editing.isNew&&confirm(`Excluir “${editing.name}”?`)){persist(items.filter(x=>x.id!==editing.id));setEditing(null);appAction('Orçamento excluído.')}};
  const totalLimit=items.reduce((s,x)=>s+Number(x.limit),0),totalSpent=items.reduce((s,x)=>s+spent(x),0);
  return <div className="page-stack budgets-page"><div className="page-heading"><div><p>Planejamento mensal</p><h1>Orçamentos</h1><span>Escolha onde gastar e respeite seus limites.</span></div><div className="budget-actions"><input className="ghost toolbar-month" type="month" value={period} onChange={e=>setPeriod(e.target.value)}/><button className="primary" onClick={openNew}><Plus size={18}/> Novo orçamento</button></div></div><div className="metrics-grid compact"><MetricCard label="Limite planejado" value={brl(totalLimit)} detail="Todos os temas" icon={Target} tone="purple"/><MetricCard label="Valor utilizado" value={brl(totalSpent)} detail={`${Math.round(totalSpent/totalLimit*100)||0}% do total`} icon={TrendingDown} tone="negative"/><MetricCard label="Ainda disponível" value={brl(Math.max(0,totalLimit-totalSpent))} detail="Para o restante do mês" icon={WalletCards} tone="positive"/></div><div className="budget-grid">{items.map(b=>{const used=spent(b),pct=Math.min(100,Math.round(used/b.limit*100)||0),remaining=b.limit-used;return <article className={`card budget-card ${remaining<0?'over':''}`} key={b.id}><button className="budget-edit" onClick={()=>setEditing({...b,limit:String(b.limit).replace('.',',')})} aria-label={`Editar ${b.name}`}><MoreHorizontal size={18}/></button><div className="budget-icon" style={{background:`${b.color}18`,color:b.color}}>{b.icon}</div><span>{b.theme==='fixed'?'DESPESA FIXA':b.theme==='leisure'?'LAZER':b.theme==='saving'?'RESERVA':'VARIÁVEL'}</span><h3>{b.name}</h3><small>{b.category}</small><div className="budget-values"><b>{brl(used)}</b><span>de {brl(b.limit)}</span></div><div className="progress"><span style={{width:`${pct}%`,background:remaining<0?'#c13d4e':b.color}}/></div><div className="budget-foot"><span>{pct}% utilizado</span><strong className={remaining<0?'down':'up'}>{remaining<0?`${brl(Math.abs(remaining))} acima`:`${brl(remaining)} disponível`}</strong></div></article>})}</div>
    {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal budget-editor" onSubmit={save}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVO ORÇAMENTO':'EDITAR ORÇAMENTO'}</span><h2>{editing.isNew?'Criar limite de gastos':'Atualizar limite'}</h2><p>Escolha o tema e quanto deseja gastar.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="budget-edit-grid"><label className="field-full">Nome do orçamento<input value={editing.name} onChange={e=>setEditing({...editing,name:e.target.value})} placeholder="Ex.: Lazer de fim de semana" required/></label><label>Tema<select value={editing.theme} onChange={e=>setEditing({...editing,theme:e.target.value})}><option value="fixed">Despesa fixa</option><option value="leisure">Lazer</option><option value="variable">Gasto variável</option><option value="saving">Reserva</option></select></label><label>Categoria<select value={editing.category} onChange={e=>setEditing({...editing,category:e.target.value})}>{categories.map(x=><option key={x}>{x}</option>)}</select></label><label>Limite mensal<input value={editing.limit} onChange={e=>setEditing({...editing,limit:e.target.value.replace(/[^0-9,.]/g,'')})} placeholder="0,00" inputMode="decimal" required/></label><label>Ícone<input value={editing.icon} onChange={e=>setEditing({...editing,icon:e.target.value})} maxLength={4}/></label><label>Cor<input type="color" value={editing.color} onChange={e=>setEditing({...editing,color:e.target.value})}/></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={remove}>Excluir orçamento</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar orçamento</button></div></form></div>}
  </div>
}
function AccountsPage({people,setPeople,balances,setBalances}:{people:any;setPeople:any;balances:any;setBalances:any}) {
  const [accounts,setAccounts]=useState<any[]>([]); const [editing,setEditing]=useState<any|null>(null); const [transfer,setTransfer]=useState<any|null>(null);
  useEffect(()=>{const saved=localStorage.getItem('juntos-accounts');setAccounts(saved?JSON.parse(saved):[])},[]);
  const persist=(next:any[])=>{setAccounts(next);localStorage.setItem('juntos-accounts',JSON.stringify(next));const nextBalances={...balances,couple:0,rafael:0,mariana:0,investments:0};next.forEach(a=>{if(a.id in nextBalances)nextBalances[a.id]=Number(a.value)});setBalances(nextBalances);localStorage.setItem('juntos-balances',JSON.stringify(nextBalances))};
  const openNew=()=>setEditing({id:'account-'+Date.now(),name:'',bank:'',type:'Conta corrente',value:'',color:'violet',isNew:true});
  const saveAccount=(e:React.FormEvent)=>{e.preventDefault();const value=Number(String(editing.value).replace(/[.]/g,'').replace(',','.'));if(!editing.name.trim()||!editing.bank.trim()||Number.isNaN(value))return;const account={...editing,name:editing.name.trim(),bank:editing.bank.trim(),value};delete account.isNew;const next=editing.isNew?[...accounts,account]:accounts.map(a=>a.id===account.id?account:a);persist(next);if(account.id==='rafael')setPeople({...people,Rafael:{...people.Rafael,name:account.name}});if(account.id==='mariana')setPeople({...people,Mariana:{...people.Mariana,name:account.name}});setEditing(null);appAction(editing.isNew?'Conta criada com sucesso.':'Conta atualizada em todo o aplicativo.')};
  const deleteAccount=()=>{if(!editing||!confirm(`Excluir a conta ${editing.name}?`))return;persist(accounts.filter(a=>a.id!==editing.id));setEditing(null);appAction('Conta excluída.')};
  const saveTransfer=(e:React.FormEvent)=>{e.preventDefault();const value=Number(String(transfer.value).replace(/[.]/g,'').replace(',','.'));if(!transfer.from||!transfer.to||transfer.from===transfer.to||value<=0)return;const origin=accounts.find(a=>a.id===transfer.from);if(!origin||origin.value<value){alert('Saldo insuficiente na conta de origem.');return}persist(accounts.map(a=>a.id===transfer.from?{...a,value:a.value-value}:a.id===transfer.to?{...a,value:a.value+value}:a));setTransfer(null);appAction('Transferência concluída com sucesso.')};
  const total=accounts.reduce((sum,a)=>sum+Number(a.value||0),0);
  return <div className="page-stack"><div className="page-heading"><div><p>Patrimônio</p><h1>Contas</h1><span>Todos os saldos em um só lugar.</span></div><button className="primary" onClick={openNew}><Plus size={18}/> Nova conta</button></div><div className="account-grid">{accounts.length?accounts.map(a=><article className="card account" key={a.id}><div className={`bank-icon ${a.color}`}><Landmark/></div><button className="icon-button" onClick={()=>setEditing({...a,value:String(a.value).replace('.',',')})} aria-label={`Editar ${a.name}`}><MoreHorizontal size={18}/></button><span>{a.bank}</span><h3>{a.name}</h3><small>{a.type}</small><strong>{brl(a.value)}</strong><div className="account-foot"><span>Sem movimentações</span></div></article>):<div className="organizer-empty">Nenhuma conta cadastrada.</div>}</div><section className="card table-card"><div className="section-title"><div><h3>Visão consolidada</h3><p>Saldo por instituição</p></div><button className="ghost" disabled={accounts.length<2} onClick={()=>setTransfer({from:accounts[0]?.id||'',to:accounts[1]?.id||'',value:''})}>Transferir entre contas</button></div><div className="metrics-grid compact"><MetricCard label="Saldo total" value={brl(total)} detail={`${accounts.length} contas cadastradas`} icon={WalletCards} tone="purple"/><MetricCard label="Entradas" value={brl(0)} detail="Sem movimentações" icon={TrendingUp} tone="positive"/><MetricCard label="Saídas" value={brl(0)} detail="Sem movimentações" icon={TrendingDown} tone="negative"/></div><div className="bar-wrap"><ResponsiveContainer width="100%" height="100%"><ReBarChart data={accounts} layout="vertical" margin={{left:20,right:30}}><CartesianGrid strokeDasharray="4 4" horizontal={false}/><XAxis type="number" hide/><YAxis type="category" dataKey="bank" axisLine={false} tickLine={false}/><Tooltip formatter={(v)=>brl(Number(v))}/><Bar dataKey="value" fill="#7f2854" radius={[0,8,8,0]}/></ReBarChart></ResponsiveContainer></div></section>
    {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal account-editor" onSubmit={saveAccount}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVA CONTA':'EDITAR CONTA'}</span><h2>{editing.isNew?'Adicionar conta':'Configurar conta'}</h2><p>Atualize todas as informações e o saldo.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X size={19}/></button></div><div className="account-edit-grid"><label>Nome da conta<input value={editing.name} onChange={e=>setEditing({...editing,name:e.target.value})} required/></label><label>Instituição<input value={editing.bank} onChange={e=>setEditing({...editing,bank:e.target.value})} placeholder="Ex.: Nubank" required/></label><label>Tipo<select value={editing.type} onChange={e=>setEditing({...editing,type:e.target.value})}><option>Conta corrente</option><option>Conta individual</option><option>Carteira</option><option>Investimentos</option><option>Poupança</option></select></label><label>Saldo<input value={editing.value} onChange={e=>setEditing({...editing,value:e.target.value.replace(/[^0-9,.]/g,'')})} inputMode="decimal" required/></label><label>Cor<select value={editing.color} onChange={e=>setEditing({...editing,color:e.target.value})}><option value="violet">Roxo</option><option value="orange">Laranja</option><option value="amber">Amarelo</option><option value="dark">Preto</option></select></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger delete-account" onClick={deleteAccount}>Excluir conta</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar conta</button></div></form></div>}
    {transfer&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setTransfer(null)}><form className="modal transfer-modal" onSubmit={saveTransfer}><div className="edit-modal-head"><div><span>MOVIMENTAÇÃO INTERNA</span><h2>Transferir entre contas</h2><p>O valor será debitado da origem e creditado no destino.</p></div><button type="button" className="icon-button" onClick={()=>setTransfer(null)}><X size={19}/></button></div><div className="account-edit-grid"><label>Conta de origem<select value={transfer.from} onChange={e=>setTransfer({...transfer,from:e.target.value})}>{accounts.map(a=><option value={a.id} key={a.id}>{a.name} — {brl(a.value)}</option>)}</select></label><label>Conta de destino<select value={transfer.to} onChange={e=>setTransfer({...transfer,to:e.target.value})}>{accounts.map(a=><option value={a.id} key={a.id}>{a.name}</option>)}</select></label><label className="field-full">Valor da transferência<input value={transfer.value} onChange={e=>setTransfer({...transfer,value:e.target.value.replace(/[^0-9,.]/g,'')})} placeholder="0,00" inputMode="decimal" required/></label></div><div className="edit-modal-actions"><span/><button type="button" className="ghost" onClick={()=>setTransfer(null)}>Cancelar</button><button className="primary">Confirmar transferência</button></div></form></div>}
  </div>
}

function CardsPage({people}:{people:any}){
  const defaultCards:any[]=[];
  const [cards,setCards]=useState<any[]>(defaultCards); const [selectedId,setSelectedId]=useState('nubank-4821'); const [editing,setEditing]=useState<any|null>(null); const [details,setDetails]=useState(false); const [purchases,setPurchases]=useState<any[]>(transactions.filter(t=>t.type==='out'));
  useEffect(()=>{const saved=localStorage.getItem('juntos-cards');if(saved){const parsed=JSON.parse(saved);setCards(parsed);if(parsed[0])setSelectedId(parsed[0].id)}const load=()=>{const tx=localStorage.getItem('juntos-transactions');setPurchases((tx?JSON.parse(tx):transactions).filter((t:any)=>t.type==='out'))};load();window.addEventListener('juntos-transactions-updated',load);return()=>window.removeEventListener('juntos-transactions-updated',load)},[]);
  const persist=(next:any[])=>{setCards(next);localStorage.setItem('juntos-cards',JSON.stringify(next))}; const card=cards.find(c=>c.id===selectedId)||cards[0];
  const openNew=()=>setEditing({id:'card-'+Date.now(),bank:'',last4:'',holder:people.Rafael.name.toUpperCase()||'',tier:'platinum',invoice:'0',limit:'0',closing:new Date().toISOString().slice(0,10),bestDay:'',future:'0',color:'purple',isNew:true});
  const saveCard=(e:React.FormEvent)=>{e.preventDefault();const clean={...editing,invoice:Number(String(editing.invoice).replace(/[.]/g,'').replace(',','.')),limit:Number(String(editing.limit).replace(/[.]/g,'').replace(',','.')),future:Number(String(editing.future).replace(/[.]/g,'').replace(',','.'))};delete clean.isNew;if(!clean.bank.trim()||clean.last4.length!==4||!clean.holder.trim()||clean.limit<=0||!clean.closing){appAction('Preencha os dados obrigat?rios e informe um limite maior que zero.');return}const next=editing.isNew?[...cards,clean]:cards.map(c=>c.id===clean.id?clean:c);persist(next);setSelectedId(clean.id);setEditing(null);appAction(editing.isNew?'Cartão criado com sucesso.':'Cartão atualizado com sucesso.')};
  const removeCard=()=>{if(!editing||!confirm(`Excluir o cartão ${editing.bank}?`))return;const next=cards.filter(c=>c.id!==editing.id);persist(next);setSelectedId(next[0]?.id||'');setEditing(null);appAction('Cartão excluído.')};
  const pay=()=>{if(!card||!confirm(`Confirmar pagamento de ${brl(card.invoice)}?`))return;persist(cards.map(c=>c.id===card.id?{...c,invoice:0}:c));appAction('Fatura paga com sucesso.')};
  if(!card)return <div className="page-stack"><div className="page-heading"><div><p>Crédito</p><h1>Cartões</h1><span>Nenhum cartão cadastrado.</span></div><button className="primary" onClick={openNew}><Plus size={18}/> Novo cartão</button></div>{editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal card-editor" onSubmit={saveCard}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVO CARTÃO':'EDITAR CARTÃO'}</span><h2>{editing.isNew?'Adicionar cartão':'Configurar cartão'}</h2><p>Edite todos os dados, limites e datas.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="card-edit-grid"><label>Instituição<input value={editing.bank} onChange={e=>setEditing({...editing,bank:e.target.value})} required/></label><label>Últimos 4 dígitos<input value={editing.last4} maxLength={4} onChange={e=>setEditing({...editing,last4:e.target.value.replace(/\D/g,'')})} required/></label><label>Titular<input value={editing.holder} onChange={e=>setEditing({...editing,holder:e.target.value})} required/></label><label>Categoria<select value={editing.tier} onChange={e=>setEditing({...editing,tier:e.target.value})}><option>platinum</option><option>gold</option><option>black</option><option>internacional</option></select></label><label>Fatura atual<input value={editing.invoice} onChange={e=>setEditing({...editing,invoice:e.target.value.replace(/[^0-9,.]/g,'')})}/></label><label>Limite total<input value={editing.limit} onChange={e=>setEditing({...editing,limit:e.target.value.replace(/[^0-9,.]/g,'')})}/></label><label>Próximo fechamento<input type="date" value={editing.closing} onChange={e=>setEditing({...editing,closing:e.target.value})}/></label><label>Melhor dia<input value={editing.bestDay} onChange={e=>setEditing({...editing,bestDay:e.target.value})}/></label><label>Parcelas futuras<input value={editing.future} onChange={e=>setEditing({...editing,future:e.target.value.replace(/[^0-9,.]/g,'')})}/></label><label>Cor<select value={editing.color} onChange={e=>setEditing({...editing,color:e.target.value})}><option value="purple">Roxo</option><option value="wine">Vinho</option><option value="blue">Azul</option><option value="black">Preto</option></select></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={removeCard}>Excluir cartão</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar cartão</button></div></form></div>}</div>;
  const used=Math.min(100,Math.round(card.invoice/card.limit*100)||0); const closingLabel=new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'long'}).format(new Date(card.closing+'T12:00:00'));
  return <div className="page-stack"><div className="page-heading"><div><p>Crédito</p><h1>Cartões</h1><span>Limites e faturas sob controle.</span></div><button className="primary" onClick={openNew}><Plus size={18}/> Novo cartão</button></div>{cards.length>1&&<div className="card-tabs">{cards.map(c=><button className={c.id===card.id?'active':''} onClick={()=>setSelectedId(c.id)} key={c.id}>{c.bank} •••• {c.last4}</button>)}</div>}<div className="cards-layout"><button className={`credit-card visual-nubank card-visual-button ${card.color}`} onClick={()=>setEditing({...card,invoice:String(card.invoice).replace('.',','),limit:String(card.limit).replace('.',','),future:String(card.future).replace('.',',')})}><div><span>{card.bank}</span><CreditCard/></div><b>•••• •••• •••• {card.last4}</b><div><span>{card.holder}</span><strong>{card.tier}</strong></div><small>Clique para editar</small></button><section className="card invoice"><span>Fatura atual</span><h2>{brl(card.invoice)}</h2><div className="progress"><span style={{width:`${used}%`}}/></div><div><span>Limite usado: {used}%</span><b>Disponível: {brl(Math.max(0,card.limit-card.invoice))}</b></div><button className="primary" onClick={pay} disabled={card.invoice<=0}>{card.invoice>0?'Pagar fatura':'Fatura paga'}</button></section><section className="card invoice"><span>Próximo fechamento</span><h2>{closingLabel}</h2><p>Melhor dia para compra: <b>{card.bestDay}</b></p><div className="invoice-alert"><Lightbulb/> Suas parcelas futuras somam {brl(card.future)}</div><button className="ghost" onClick={()=>setDetails(true)}>Ver detalhes</button></section></div><section className="card table-card"><div className="section-title"><div><h3>Compras no cartão</h3><p>Fatura atual</p></div><button className="text-button" onClick={()=>appAction({page:'Transações'})}>Ver fatura completa <ArrowRight size={15}/></button></div><div className="transaction-list large">{purchases.length?purchases.map(t=><div className="transaction" key={t.id}><div className="transaction-icon out">{t.icon}</div><div className="transaction-name"><b>{displayTitle(people,t.title)}</b><span>{t.category}</span></div><span className="person-pill">{displayPerson(people,t.person)}</span><div className="transaction-date">{t.date}</div><strong>− {brl(t.value)}</strong></div>):<div className="organizer-empty">Nenhuma compra cadastrada neste cartão.</div>}</div></section>
    {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal card-editor" onSubmit={saveCard}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVO CARTÃO':'EDITAR CARTÃO'}</span><h2>{editing.isNew?'Adicionar cartão':'Configurar cartão'}</h2><p>Edite todos os dados, limites e datas.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="card-edit-grid"><label>Instituição<input value={editing.bank} onChange={e=>setEditing({...editing,bank:e.target.value})} required/></label><label>Últimos 4 dígitos<input value={editing.last4} maxLength={4} onChange={e=>setEditing({...editing,last4:e.target.value.replace(/\D/g,'')})} required/></label><label>Titular<input value={editing.holder} onChange={e=>setEditing({...editing,holder:e.target.value})} required/></label><label>Categoria<select value={editing.tier} onChange={e=>setEditing({...editing,tier:e.target.value})}><option>platinum</option><option>gold</option><option>black</option><option>internacional</option></select></label><label>Fatura atual<input value={editing.invoice} onChange={e=>setEditing({...editing,invoice:e.target.value.replace(/[^0-9,.]/g,'')})}/></label><label>Limite total<input value={editing.limit} onChange={e=>setEditing({...editing,limit:e.target.value.replace(/[^0-9,.]/g,'')})}/></label><label>Próximo fechamento<input type="date" value={editing.closing} onChange={e=>setEditing({...editing,closing:e.target.value})}/></label><label>Melhor dia<input value={editing.bestDay} onChange={e=>setEditing({...editing,bestDay:e.target.value})}/></label><label>Parcelas futuras<input value={editing.future} onChange={e=>setEditing({...editing,future:e.target.value.replace(/[^0-9,.]/g,'')})}/></label><label>Cor<select value={editing.color} onChange={e=>setEditing({...editing,color:e.target.value})}><option value="purple">Roxo</option><option value="wine">Vinho</option><option value="blue">Azul</option><option value="black">Preto</option></select></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={removeCard}>Excluir cartão</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar cartão</button></div></form></div>}
    {details&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setDetails(false)}><div className="modal card-details"><div className="edit-modal-head"><div><span>RESUMO DO CARTÃO</span><h2>{card.bank} •••• {card.last4}</h2></div><button className="icon-button" onClick={()=>setDetails(false)}><X/></button></div><div className="details-list"><div><span>Fatura atual</span><b>{brl(card.invoice)}</b></div><div><span>Limite total</span><b>{brl(card.limit)}</b></div><div><span>Limite disponível</span><b>{brl(Math.max(0,card.limit-card.invoice))}</b></div><div><span>Próximo fechamento</span><b>{closingLabel}</b></div><div><span>Parcelas futuras</span><b>{brl(card.future)}</b></div></div><div className="edit-modal-actions"><span/><button className="primary" onClick={()=>setDetails(false)}>Fechar</button></div></div></div>}
  </div>
}

function GoalsPage(){
  const initialGoals:any[]=[];
  const [items,setItems]=useState<any[]>(initialGoals); const [editing,setEditing]=useState<any|null>(null); const [contribution,setContribution]=useState<any|null>(null);
  useEffect(()=>{const saved=localStorage.getItem('juntos-goals');if(saved)setItems(JSON.parse(saved))},[]); const persist=(next:any[])=>{setItems(next);localStorage.setItem('juntos-goals',JSON.stringify(next));window.dispatchEvent(new Event('juntos-goals-updated'))};
  const openNew=()=>setEditing({id:Date.now(),title:'',emoji:'🎯',current:'0',total:'',color:'#7c3aed',date:'Dez 2026',isNew:true});
  const save=(e:React.FormEvent)=>{e.preventDefault();const item={...editing,current:Number(String(editing.current).replace(/[.]/g,'').replace(',','.')),total:Number(String(editing.total).replace(/[.]/g,'').replace(',','.'))};delete item.isNew;if(!item.title.trim()||item.total<=0)return;persist(editing.isNew?[...items,item]:items.map(x=>x.id===item.id?item:x));setEditing(null);appAction(editing.isNew?'Meta criada com sucesso.':'Meta atualizada com sucesso.')};
  const remove=()=>{if(editing&&!editing.isNew&&confirm(`Excluir a meta “${editing.title}”?`)){persist(items.filter(x=>x.id!==editing.id));setEditing(null);appAction('Meta excluída.')}};
  const addMoney=(e:React.FormEvent)=>{e.preventDefault();const value=Number(String(contribution.value).replace(/[.]/g,'').replace(',','.'));if(value<=0)return;persist(items.map(x=>x.id===contribution.goal.id?{...x,current:x.current+value}:x));setContribution(null);appAction('Dinheiro adicionado à meta.')};
  return <div className="page-stack"><div className="page-heading"><div><p>Meus objetivos</p><h1>Metas</h1><span>Cada passo aproxima você do futuro.</span></div><button className="primary" onClick={openNew}><Plus size={18}/> Nova meta</button></div><div className="goal-page-grid">{items.map(g=>{const pct=Math.min(100,Math.round(g.current/g.total*100)||0);return <article className="card big-goal" key={g.id}><button className="goal-cover goal-cover-button" style={{background:`linear-gradient(135deg,${g.color},#24131e)`}} onClick={()=>setEditing({...g,current:String(g.current).replace('.',','),total:String(g.total).replace('.',',')})}><span>{g.emoji}</span><b>{pct}%</b><small>Clique para editar</small></button><div className="goal-body"><h3>{g.title}</h3><p>Previsão: {g.date}</p><div className="progress"><span style={{width:`${pct}%`,background:g.color}}/></div><div><b>{brl(g.current)}</b><span>Faltam {brl(Math.max(0,g.total-g.current))}</span></div><button className="ghost" onClick={()=>setContribution({goal:g,value:''})}>Adicionar dinheiro</button></div></article>})}</div>
    {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal goal-editor" onSubmit={save}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVA META':'EDITAR META'}</span><h2>{editing.isNew?'Criar uma meta':'Atualizar meta'}</h2><p>Personalize o objetivo e acompanhe o progresso.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="goal-edit-grid"><label className="field-full">Nome da meta<input value={editing.title} onChange={e=>setEditing({...editing,title:e.target.value})} placeholder="Ex.: Viagem para Itália" required/></label><label>Ícone<input value={editing.emoji} onChange={e=>setEditing({...editing,emoji:e.target.value})} maxLength={4}/></label><label>Cor<input type="color" value={editing.color} onChange={e=>setEditing({...editing,color:e.target.value})}/></label><label>Valor guardado<input value={editing.current} onChange={e=>setEditing({...editing,current:e.target.value.replace(/[^0-9,.]/g,'')})} inputMode="decimal"/></label><label>Valor da meta<input value={editing.total} onChange={e=>setEditing({...editing,total:e.target.value.replace(/[^0-9,.]/g,'')})} inputMode="decimal" required/></label><label className="field-full">Previsão de conclusão<input value={editing.date} onChange={e=>setEditing({...editing,date:e.target.value})} placeholder="Ex.: Novembro de 2027"/></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={remove}>Excluir meta</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar meta</button></div></form></div>}
    {contribution&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setContribution(null)}><form className="modal contribution-modal" onSubmit={addMoney}><div className="edit-modal-head"><div><span>NOVO APORTE</span><h2>Adicionar dinheiro</h2><p>{contribution.goal.emoji} {contribution.goal.title}</p></div><button type="button" className="icon-button" onClick={()=>setContribution(null)}><X/></button></div><div className="goal-edit-grid"><label className="field-full">Valor do aporte<input value={contribution.value} onChange={e=>setContribution({...contribution,value:e.target.value.replace(/[^0-9,.]/g,'')})} placeholder="0,00" inputMode="decimal" autoFocus required/></label></div><div className="edit-modal-actions"><span/><button type="button" className="ghost" onClick={()=>setContribution(null)}>Cancelar</button><button className="primary">Confirmar aporte</button></div></form></div>}
  </div>
}

function CalendarPage({people}:{people:any}){
  const initialEvents:any[]=[];
  const [month,setMonth]=useState(new Date(2026,6,1)); const [events,setEvents]=useState<any[]>(initialEvents); const [editing,setEditing]=useState<any|null>(null);
  useEffect(()=>{const saved=localStorage.getItem('juntos-calendar-events');if(saved)setEvents(JSON.parse(saved))},[]);
  const persist=(next:any[])=>{setEvents(next);localStorage.setItem('juntos-calendar-events',JSON.stringify(next))};
  const year=month.getFullYear(),monthIndex=month.getMonth(),daysInMonth=new Date(year,monthIndex+1,0).getDate(),startDay=new Date(year,monthIndex,1).getDay(); const cells=Array.from({length:42},(_,i)=>i-startDay+1); const monthKey=`${year}-${String(monthIndex+1).padStart(2,'0')}`;
  const openNew=(date?:string)=>setEditing({id:Date.now(),title:'',date:date||`${monthKey}-${String(Math.min(new Date().getDate(),daysInMonth)).padStart(2,'0')}`,type:'bill',value:'',person:'Rafael',notes:'',isNew:true});
  const save=(e:React.FormEvent)=>{e.preventDefault();const item={...editing,value:Number(String(editing.value||0).replace(/[.]/g,'').replace(',','.'))};delete item.isNew;persist(editing.isNew?[...events,item]:events.map(x=>x.id===item.id?item:x));setEditing(null);appAction(editing.isNew?'Evento criado no calendário.':'Evento atualizado com sucesso.')};
  const remove=()=>{if(editing&&!editing.isNew&&confirm(`Excluir “${editing.title}”?`)){persist(events.filter(x=>x.id!==editing.id));setEditing(null);appAction('Evento excluído do calendário.')}};
  const monthEvents=events.filter(e=>e.date.startsWith(monthKey)); const upcoming=[...events].filter(e=>e.date>=`${monthKey}-01`).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,5); const title=new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(month).replace(/^./,x=>x.toUpperCase());
  return <div className="page-stack"><div className="page-heading"><div><p>Minha agenda</p><h1>Calendário financeiro</h1><span>Nenhum compromisso fica para trás.</span></div><button className="primary" onClick={()=>openNew()}><Plus size={18}/> Novo evento</button></div><div className="calendar-layout"><section className="card calendar"><div className="calendar-head"><button className="icon-button" onClick={()=>setMonth(new Date(year,monthIndex-1,1))} aria-label="Mês anterior">‹</button><h3>{title}</h3><button className="icon-button" onClick={()=>setMonth(new Date(year,monthIndex+1,1))} aria-label="Próximo mês">›</button><button className="ghost" onClick={()=>setMonth(new Date())}>Hoje</button></div><div className="weekdays">{['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(x=><b key={x}>{x}</b>)}</div><div className="days">{cells.map((day,i)=>{const valid=day>=1&&day<=daysInMonth;const date=valid?`${monthKey}-${String(day).padStart(2,'0')}`:'';const dayEvents=valid?monthEvents.filter(e=>e.date===date):[];return <div className={!valid?'muted':date===new Date().toISOString().slice(0,10)?'today':''} key={i} onDoubleClick={()=>valid&&openNew(date)}><button className="day-number" onClick={()=>valid&&openNew(date)} disabled={!valid}>{valid?day:''}</button>{dayEvents.map(e=><button className={`calendar-event ${e.type}`} onClick={()=>setEditing({...e,value:String(e.value).replace('.',',')})} key={e.id}>{e.title}</button>)}</div>})}</div><small className="calendar-hint">Clique no número do dia para adicionar. Clique no evento para editar.</small></section><aside className="card agenda"><h3>Próximos eventos</h3>{upcoming.length?upcoming.map(e=><button className="agenda-date" onClick={()=>setEditing({...e,value:String(e.value).replace('.',',')})} key={e.id}><b>{e.date.slice(-2)}</b><span>{new Intl.DateTimeFormat('pt-BR',{weekday:'short'}).format(new Date(e.date+'T12:00:00')).toUpperCase()}<small>{e.title}</small></span><strong>{e.value?brl(e.value):'—'}</strong></button>):<p className="agenda-empty">Nenhum evento agendado.</p>}<div className="ai-mini"><Sparkles/><p><b>Agenda organizada!</b> Clique em qualquer compromisso para atualizar.</p></div></aside></div>
    {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal calendar-editor" onSubmit={save}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVO EVENTO':'EDITAR EVENTO'}</span><h2>{editing.isNew?'Adicionar compromisso':'Atualizar compromisso'}</h2><p>Organize datas, valores e responsáveis.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="calendar-edit-grid"><label className="field-full">Título<input value={editing.title} onChange={e=>setEditing({...editing,title:e.target.value})} placeholder="Ex.: Conta de energia" required/></label><label>Data<input type="date" value={editing.date} onChange={e=>setEditing({...editing,date:e.target.value})} required/></label><label>Tipo<select value={editing.type} onChange={e=>setEditing({...editing,type:e.target.value})}><option value="bill">Conta</option><option value="income">Receita</option><option value="card">Cartão</option><option value="sub">Assinatura</option><option value="goal">Meta</option></select></label><label>Valor<input value={editing.value} onChange={e=>setEditing({...editing,value:e.target.value.replace(/[^0-9,.]/g,'')})} placeholder="0,00" inputMode="decimal"/></label><label>Responsável<select value={editing.person} onChange={e=>setEditing({...editing,person:e.target.value})}><option value="Rafael">{people.Rafael.name.split(' ')[0]||'Você'}</option></select></label><label className="field-full">Observações<textarea value={editing.notes||''} onChange={e=>setEditing({...editing,notes:e.target.value})} placeholder="Detalhes opcionais" rows={3}/></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={remove}>Excluir evento</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar evento</button></div></form></div>}
  </div>
}

function SubscriptionsPage(){
  const initial:any[]=[];
  const [items,setItems]=useState<any[]>(initial); const [editing,setEditing]=useState<any|null>(null);
  useEffect(()=>{const saved=localStorage.getItem('juntos-subscriptions');if(saved)setItems(JSON.parse(saved))},[]); const persist=(next:any[])=>{setItems(next);localStorage.setItem('juntos-subscriptions',JSON.stringify(next))};
  const openNew=()=>setEditing({id:Date.now(),name:'',category:'Entretenimento',value:'',next:'2026-07-20',icon:'★',active:true,isNew:true});
  const save=(e:React.FormEvent)=>{e.preventDefault();const item={...editing,value:Number(String(editing.value).replace(/[.]/g,'').replace(',','.'))};delete item.isNew;if(!item.name.trim()||item.value<0)return;persist(editing.isNew?[...items,item]:items.map(x=>x.id===item.id?item:x));setEditing(null);appAction(editing.isNew?'Assinatura criada com sucesso.':'Assinatura atualizada com sucesso.')};
  const remove=()=>{if(editing&&!editing.isNew&&confirm(`Excluir “${editing.name}”?`)){persist(items.filter(x=>x.id!==editing.id));setEditing(null);appAction('Assinatura excluída.')}}; const active=items.filter(x=>x.active); const monthly=active.reduce((sum,x)=>sum+Number(x.value),0); const paused=items.filter(x=>!x.active).reduce((sum,x)=>sum+Number(x.value),0);
  return <div className="page-stack"><div className="page-heading"><div><p>Gastos recorrentes</p><h1>Assinaturas</h1><span>Pequenos valores também contam.</span></div><button className="primary" onClick={openNew}><Plus size={18}/> Nova assinatura</button></div><div className="metrics-grid compact"><MetricCard label="Total mensal" value={brl(monthly)} detail={`${active.length} assinaturas ativas`} icon={Zap} tone="purple"/><MetricCard label="Custo anual" value={brl(monthly*12)} detail="Projeção para 12 meses" icon={CalendarDays}/><MetricCard label="Economia com pausas" value={brl(paused)} detail={`${items.length-active.length} pausadas`} icon={TrendingDown} tone="positive"/></div><div className="subscription-grid">{items.map(s=><article className={`card subscription ${!s.active?'paused':''}`} key={s.id}><div className="sub-logo">{s.icon}</div><button className="icon-button" onClick={()=>setEditing({...s,value:String(s.value).replace('.',',')})}><MoreHorizontal size={17}/></button><h3>{s.name}</h3><p>{s.category}</p><strong>{brl(Number(s.value))}<small>/mês</small></strong><div><span>Próxima cobrança</span><b>{new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(s.next+'T12:00:00')).replace('.','')}</b></div><span className={`subscription-status ${s.active?'active':'paused'}`}>{s.active?'Ativa':'Pausada'}</span><button className="ghost" onClick={()=>setEditing({...s,value:String(s.value).replace('.',',')})}>Gerenciar</button></article>)}</div>
    {editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal subscription-editor" onSubmit={save}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVA ASSINATURA':'EDITAR ASSINATURA'}</span><h2>{editing.isNew?'Adicionar assinatura':'Gerenciar assinatura'}</h2><p>Atualize cobrança, categoria e situação.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="subscription-edit-grid"><label className="field-full">Nome<input value={editing.name} onChange={e=>setEditing({...editing,name:e.target.value})} placeholder="Ex.: Netflix" required/></label><label>Categoria<select value={editing.category} onChange={e=>setEditing({...editing,category:e.target.value})}><option>Entretenimento</option><option>Música</option><option>Saúde</option><option>Armazenamento</option><option>Educação</option><option>Produtividade</option><option>Transporte</option><option>Outros</option></select></label><label>Ícone<input value={editing.icon} onChange={e=>setEditing({...editing,icon:e.target.value})} maxLength={3}/></label><label>Valor mensal<input value={editing.value} onChange={e=>setEditing({...editing,value:e.target.value.replace(/[^0-9,.]/g,'')})} inputMode="decimal" required/></label><label>Próxima cobrança<input type="date" value={editing.next} onChange={e=>setEditing({...editing,next:e.target.value})} required/></label><div className="subscription-active field-full"><span><b>Assinatura ativa</b><small>Desative para pausar a cobrança nos totais</small></span><button type="button" className={`toggle ${editing.active?'on':''}`} onClick={()=>setEditing({...editing,active:!editing.active})}><i/></button></div></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={remove}>Excluir assinatura</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar assinatura</button></div></form></div>}
  </div>
}

function ReportsPage({people}:{people:any}){
  const [view,setView]=useState('Mensal'); const [tx,setTx]=useState<any[]>(transactions); const [accounts,setAccounts]=useState<any[]>([]); const [cards,setCards]=useState<any[]>([]);
  useEffect(()=>{const savedTx=localStorage.getItem('juntos-transactions'),savedAccounts=localStorage.getItem('juntos-accounts'),savedCards=localStorage.getItem('juntos-cards');if(savedTx)setTx(JSON.parse(savedTx));if(savedAccounts)setAccounts(JSON.parse(savedAccounts));if(savedCards)setCards(JSON.parse(savedCards))},[]);
  const income=tx.filter(t=>t.type==='in').reduce((s,t)=>s+Number(t.value),0),expense=tx.filter(t=>t.type==='out').reduce((s,t)=>s+Number(t.value),0); const categories=Object.values(tx.filter(t=>t.type==='out').reduce((acc:any,t:any)=>{acc[t.category]??={name:t.category,value:0};acc[t.category].value+=Number(t.value);return acc},{})) as any[]; const categoryColors=['#752548','#9f4a78','#7c3aed','#d78faf','#db8b24','#0f9f6e'];
  const rows=()=>view==='Por categoria'?categories.map((x:any)=>[x.name,brl(x.value)]):view==='Por cartão'?cards.map((c:any)=>[c.bank+' •••• '+c.last4,brl(c.invoice),brl(c.limit)]):view==='Por banco'?accounts.map((a:any)=>[a.bank,a.name,brl(a.value)]):view==='Anual'?cashflow.map((x:any)=>[x.m,brl(x.receita),brl(x.despesa),brl(x.receita-x.despesa)]):tx.map((t:any)=>[t.date,displayTitle(people,t.title),t.category,displayPerson(people,t.person),t.type==='in'?brl(t.value):'- '+brl(t.value)]);
  const headers=()=>view==='Por categoria'?['Categoria','Total']:view==='Por cartão'?['Cartão','Fatura','Limite']:view==='Por banco'?['Banco','Conta','Saldo']:view==='Anual'?['Mês','Receitas','Despesas','Resultado']:['Data','Descrição','Categoria','Pessoa','Valor'];
  const exportExcel=()=>{const table=[headers(),...rows()];const html=`<table>${table.map((r,i)=>`<tr>${r.map(c=>`<${i?'td':'th'}>${c}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</table>`;const blob=new Blob([html],{type:'application/vnd.ms-excel;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`relatorio-${view.toLowerCase().replace(/ /g,'-')}.xls`;a.click();URL.revokeObjectURL(url);appAction('Relatório Excel exportado.')};
  const exportPdf=()=>{const win=window.open('','_blank','width=900,height=700');if(!win)return;win.document.write(`<html><head><title>Relatório ${view}</title><style>body{font-family:Arial;padding:32px;color:#241820}h1{color:#7f2854}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #ddd;text-align:left}th{background:#f6eff2}</style></head><body><h1>Juntos Finance — ${view}</h1><p>Receitas: ${brl(income)} | Despesas: ${brl(expense)} | Resultado: ${brl(income-expense)}</p><table><thead><tr>${headers().map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows().map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table><script>window.onload=()=>window.print()<\/script></body></html>`);win.document.close()};
  return <div className="page-stack reports-page"><div className="page-heading"><div><p>Análises financeiras</p><h1>Relatórios</h1><span>Entenda seus números e tome decisões melhores.</span></div><div className="report-export"><button className="ghost" onClick={exportPdf}><Download size={17}/> Exportar PDF</button><button className="primary" onClick={exportExcel}><Download size={17}/> Excel</button></div></div><div className="report-tabs">{['Mensal','Anual','Por categoria','Por cartão','Por banco'].map(x=><button className={view===x?'active':''} onClick={()=>setView(x)} key={x}>{x}</button>)}</div><div className="metrics-grid compact"><MetricCard label="Receitas" value={brl(income)} detail="Período selecionado" icon={TrendingUp} tone="positive"/><MetricCard label="Despesas" value={brl(expense)} detail="Período selecionado" icon={TrendingDown} tone="negative"/><MetricCard label="Resultado" value={brl(income-expense)} detail={income-expense>=0?'Positivo':'Negativo'} icon={WalletCards} tone="purple"/></div>{view==='Anual'&&<section className="card report-chart"><h3>Visão anual</h3><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><ReBarChart data={cashflow}><CartesianGrid vertical={false} stroke="#eee7eb"/><XAxis dataKey="m" axisLine={false} tickLine={false}/><YAxis hide/><Tooltip formatter={v=>brl(Number(v))}/><Bar dataKey="receita" fill="#2f9961" radius={[5,5,0,0]}/><Bar dataKey="despesa" fill="#8b263f" radius={[5,5,0,0]}/></ReBarChart></ResponsiveContainer></div></section>}{view==='Por categoria'&&<section className="card report-chart category-report"><h3>Despesas por categoria</h3><div className="report-category-layout"><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={categories} dataKey="value" nameKey="name" innerRadius={65} outerRadius={95}>{categories.map((x,i)=><Cell key={x.name} fill={categoryColors[i%categoryColors.length]}/>)}</Pie><Tooltip formatter={v=>brl(Number(v))}/></PieChart></ResponsiveContainer></div><div>{categories.map((x,i)=><p key={x.name}><i style={{background:categoryColors[i%categoryColors.length]}}/><span>{x.name}</span><b>{brl(x.value)}</b></p>)}</div></div></section>}<section className="card report-table-card"><div className="section-title"><div><h3>Detalhamento — {view}</h3><p>{rows().length} registros encontrados</p></div></div><div className="report-table-wrap"><table><thead><tr>{headers().map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows().map((r,i)=><tr key={i}>{r.map((c,j)=><td key={j}>{c}</td>)}</tr>)}</tbody></table></div></section></div>
}
function AiPage({people}:{people:any}){
  const [msg,setMsg]=useState("");
  const [chat,setChat]=useState<any[]>([{from:'ai',text:'Ol?! Eu analiso somente os dados cadastrados no Juntos Finance. Pergunte sobre receitas, despesas, saldo, categorias, cart?es ou metas.'}]);
  const [data,setData]=useState({transactions:[] as any[],accounts:[] as any[],cards:[] as any[],goals:[] as any[]});
  useEffect(()=>{const load=()=>{const read=(key:string)=>{try{return JSON.parse(localStorage.getItem(key)||'[]')}catch{return[]}};setData({transactions:read('juntos-transactions'),accounts:read('juntos-accounts'),cards:read('juntos-cards'),goals:read('juntos-goals')})};load();window.addEventListener('juntos-transactions-updated',load);return()=>window.removeEventListener('juntos-transactions-updated',load)},[]);
  const totals=useMemo(()=>{const income=data.transactions.filter(item=>item.type==='in').reduce((sum,item)=>sum+Number(item.value||0),0);const expense=data.transactions.filter(item=>item.type==='out').reduce((sum,item)=>sum+Number(item.value||0),0);const categories=Object.entries(data.transactions.filter(item=>item.type==='out').reduce((groups:Record<string,number>,item:any)=>{groups[item.category||'Outros']=(groups[item.category||'Outros']||0)+Number(item.value||0);return groups},{})).sort((a,b)=>b[1]-a[1]);const accountBalance=data.accounts.reduce((sum,item)=>sum+Number(item.value||0),0);const invoices=data.cards.reduce((sum,item)=>sum+Number(item.invoice||0),0);return {income,expense,balance:income-expense,categories,accountBalance,invoices}},[data]);
  const normalize=(value:string)=>value.normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();
  const answer=(question:string)=>{const query=normalize(question);const count=data.transactions.length;const source=`C?lculo baseado em ${count} transa??o${count===1?'':'?es'} cadastrada${count===1?'':'s'}.`;if(!count&&!(data.accounts.length||data.cards.length||data.goals.length))return 'Ainda n?o existem dados suficientes para responder com n?meros. Cadastre uma receita, despesa, conta, cart?o ou meta primeiro.';if(query.includes('resumo')||query.includes('situacao')||query.includes('como estou'))return `Seu resumo: receitas de ${brl(totals.income)}, despesas de ${brl(totals.expense)} e resultado de ${brl(totals.balance)}. ${totals.balance>=0?'O resultado est? positivo.':'As despesas est?o acima das receitas.'} ${source}`;if(query.includes('receita')||query.includes('ganhei')||query.includes('entrada'))return `O total de receitas cadastradas ? ${brl(totals.income)}. ${source}`;if(query.includes('despesa')||query.includes('gastei')||query.includes('gasto total'))return `O total de despesas cadastradas ? ${brl(totals.expense)}. ${source}`;if(query.includes('saldo')||query.includes('sobrou')||query.includes('economia'))return `Receitas menos despesas resultam em ${brl(totals.balance)}. O saldo informado nas contas soma ${brl(totals.accountBalance)}. Esses valores s?o diferentes porque um ? fluxo de transa??es e o outro ? saldo cadastrado. ${source}`;if(query.includes('categoria')||query.includes('mais gasto')||query.includes('onde gasto')){const top=totals.categories[0];return top?`Sua maior categoria de despesas ? ${top[0]}, com ${brl(Number(top[1]))}, equivalente a ${totals.expense?Math.round(Number(top[1])/totals.expense*100):0}% dos gastos cadastrados. ${source}`:'N?o h? despesas categorizadas para comparar.'}if(query.includes('cartao')||query.includes('fatura')||query.includes('limite'))return data.cards.length?`Voc? possui ${data.cards.length} cart?o${data.cards.length===1?'':'?es'} cadastrado${data.cards.length===1?'':'s'}, com faturas que somam ${brl(totals.invoices)}. Limite total: ${brl(data.cards.reduce((sum,item)=>sum+Number(item.limit||0),0))}.`:'Nenhum cart?o est? cadastrado.';if(query.includes('meta')||query.includes('objetivo')){if(!data.goals.length)return 'Nenhuma meta est? cadastrada.';const remaining=data.goals.reduce((sum,item)=>sum+Math.max(0,Number(item.total||0)-Number(item.current||0)),0);return `Voc? possui ${data.goals.length} meta${data.goals.length===1?'':'s'}. Ainda faltam ${brl(remaining)} para concluir todas.`}if(query.includes('posso gastar')||query.includes('quanto gastar'))return totals.balance>0?`Pelos dados cadastrados, o resultado entre receitas e despesas ? positivo em ${brl(totals.balance)}. Isso n?o considera contas futuras ainda n?o registradas; portanto, n?o trato todo esse valor como dispon?vel sem uma reserva definida.`:`N?o h? margem positiva calculada: o resultado atual ? ${brl(totals.balance)}. Revise as maiores categorias antes de assumir novos gastos.`;if(query.includes('comecar')||query.includes('primeiro'))return 'Comece nesta ordem: cadastre suas receitas, registre despesas, informe os saldos das contas e depois defina metas. Assim os c?lculos ter?o uma base completa.';return 'N?o consigo responder essa pergunta com seguran?a usando apenas os dados dispon?veis. Posso informar: resumo financeiro, receitas, despesas, saldo, maior categoria, cart?es, faturas e metas.'};
  const send=(question=msg)=>{if(!question.trim())return;setChat(current=>[...current,{from:'user',text:question},{from:'ai',text:answer(question)}]);setMsg('')};
  const topCategory=totals.categories[0];
  return <div className="page-stack ai-page"><div className="page-heading"><div><p>Intelig?ncia financeira baseada em dados</p><h1>IA Conselheira <Sparkles size={25}/></h1><span>Respostas calculadas somente com os registros do aplicativo.</span></div></div><div className="ai-layout"><section className="card chat"><div className="chat-head"><div className="ai-icon"><Sparkles/></div><div><b>J?lia, sua conselheira</b><span><i/> Online ? {data.transactions.length} transa??es analisadas</span></div></div><div className="messages">{chat.map((message,index)=><div className={`message ${message.from}`} key={index}>{message.text}</div>)}</div><div className="suggestions">{['Qual ? meu resumo?','Onde gasto mais?','Quanto posso gastar?','Como est?o meus cart?es?'].map(question=><button key={question} onClick={()=>send(question)}>{question}</button>)}</div><div className="chat-input"><input value={msg} onChange={event=>setMsg(event.target.value)} onKeyDown={event=>event.key==='Enter'&&send()} placeholder="Pergunte sobre seus dados financeiros..."/><button onClick={()=>send()} aria-label="Enviar pergunta"><ArrowUpRight/></button></div><small className="disclaimer">Os valores s?o c?lculos dos dados cadastrados. A conselheira n?o prev? o futuro e n?o substitui orienta??o financeira profissional.</small></section><aside className="insights"><article className="card insight"><span>RESULTADO ATUAL</span><h3 className={totals.balance>=0?'up':'down'}>{brl(totals.balance)}</h3><p>{totals.balance>=0?'Receitas acima das despesas cadastradas.':'Despesas acima das receitas cadastradas.'}</p></article><article className="card insight"><span>MAIOR CATEGORIA</span><h3>{topCategory?topCategory[0]:'Sem despesas'}</h3><p>{topCategory?`${brl(Number(topCategory[1]))} em gastos registrados.`:'Cadastre despesas para gerar esta an?lise.'}</p></article><article className="card insight"><span>QUALIDADE DOS DADOS</span><h3>{data.transactions.length?'Base dispon?vel':'Base incompleta'}</h3><p>{data.transactions.length?`${data.transactions.length} movimenta??es usadas nos c?lculos.`:'Nenhuma movimenta??o cadastrada.'}</p></article></aside></div></div>
}

function SettingsPage({dark,setDark,people,setPeople}:any){
  const {configured,workspace,members,refresh,user}=useAuth();
  const [tab,setTab]=useState('Perfil');
  const [editing,setEditing]=useState<'Rafael'|'Mariana'|null>(null);
  const [currency,setCurrency]=useState('BRL');
  const [prefs,setPrefs]=useState({email:true,push:true,bills:true,goals:true,twoFactor:false});
  const [categories,setCategories]=useState(['Alimentação','Moradia','Transporte','Lazer','Assinaturas']);
  const [newCategory,setNewCategory]=useState('');
  const [sharingMode,setSharingMode]=useState<'solo'|'shared'>('solo'); const [partnerEmail,setPartnerEmail]=useState(''); const [inviteStatus,setInviteStatus]=useState('');
  useEffect(()=>{if(!user||!members.length)return;const current=members.find(member=>member.user_id===user.id);const partner=members.find(member=>member.user_id!==user.id);setPeople((previous:any)=>({Rafael:{name:current?.profiles?.full_name||previous.Rafael.name,email:current?.profiles?.email||previous.Rafael.email},Mariana:{name:partner?.profiles?.full_name||previous.Mariana.name,email:partner?.profiles?.email||previous.Mariana.email}}))},[user?.id,members.length]);
  useEffect(()=>{const saved=localStorage.getItem('juntos-settings');if(saved)try{const data=JSON.parse(saved);if(data.people)setPeople(data.people);if(data.currency)setCurrency(data.currency);if(data.prefs)setPrefs(data.prefs);if(data.categories)setCategories(data.categories);if(data.sharingMode)setSharingMode(data.sharingMode);if(data.partnerEmail)setPartnerEmail(data.partnerEmail);if(data.inviteStatus)setInviteStatus(data.inviteStatus)}catch{}},[]);
  useEffect(()=>{localStorage.setItem('juntos-settings',JSON.stringify({people,currency,prefs,categories,sharingMode,partnerEmail,inviteStatus}))},[people,currency,prefs,categories,sharingMode,partnerEmail,inviteStatus]);
  const toggle=(key:keyof typeof prefs)=>setPrefs({...prefs,[key]:!prefs[key]});
  const download=()=>{const blob=new Blob([JSON.stringify({people,currency,prefs,categories,sharingMode,partnerEmail,inviteStatus},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='juntos-finance-dados.json';a.click();URL.revokeObjectURL(url)};
  const install=async()=>{const event=(window as any).deferredInstallPrompt;if(event){await event.prompt()}else alert('No Chrome ou Edge, abra o menu do navegador e escolha “Instalar Juntos Finance”.')};
  const tabs=['Perfil','Preferências','Notificações','Privacidade e segurança','Categorias','Dados e exportação'];
  const resetSystem = () => {
    if (confirm('ATENÇÃO: Você tem certeza que deseja apagar TODOS os dados do aplicativo? Isso inclui transações, contas, metas e configurações. Esta ação não pode ser desfeita.')) {
      Object.keys(localStorage).forEach(key => {
        if (key.startsWith('juntos-')) localStorage.removeItem(key);
      });
      appAction('Sistema zerado. O aplicativo será recarregado.');
      setTimeout(() => window.location.reload(), 1500);
    }
  };
  const shareWhatsApp=()=>{const message=`Convidei você para nosso espaço no Juntos Finance. Confira o convite enviado para ${partnerEmail||'seu e-mail'}, aceite o acesso, crie sua própria senha e depois entre em ${window.location.origin}. Cada pessoa usa seu próprio login.`;window.open(`https://wa.me/?text=${encodeURIComponent(message)}`,'_blank','noopener,noreferrer')};
  const sendInvite=async()=>{
    if(!partnerEmail.includes('@'))return;
    if(!configured||!workspace){setInviteStatus('Configure o Supabase para enviar um convite real.');return}
    setInviteStatus('Enviando convite...');
    const response=await fetch('/api/invitations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:partnerEmail,workspaceId:workspace.id,role:'member'})});
    const data=await response.json();
    if(response.ok){setSharingMode('shared');setInviteStatus('Convite enviado para '+partnerEmail);appAction('Convite enviado com sucesso.');await refresh()}else setInviteStatus(data.error||'Não foi possível enviar o convite.');
  };  const personCard=(key:'Rafael'|'Mariana',who:'R'|'M')=><div><Avatar who={who} label={people[key].name}/>{editing===key?<><input value={people[key].name} onChange={e=>setPeople({...people,[key]:{...people[key],name:e.target.value}})}/><input type="email" value={people[key].email} onChange={e=>setPeople({...people,[key]:{...people[key],email:e.target.value}})}/><button className="primary" onClick={()=>setEditing(null)}>Salvar perfil</button></>:<><b>{people[key].name}</b><small>{people[key].email}</small><button className="ghost" onClick={()=>setEditing(key)}>Editar perfil</button></>}</div>;
  return <div className="page-stack"><div className="page-heading"><div><p>Seu espaço</p><h1>Configurações</h1><span>Personalize sua experiência.</span></div></div><div className="settings-layout"><aside className="card settings-nav">{tabs.map(x=><button className={tab===x?'active':''} onClick={()=>setTab(x)} key={x}>{x}<ChevronRight size={16}/></button>)}</aside><section className="card settings-content">
    {tab==='Perfil'&&<><h3>Meu perfil</h3><p>Use individualmente ou convide seu cônjuge.</p><div className="sharing-settings"><div className="sharing-choice"><button className={sharingMode==='solo'?'active':''} onClick={()=>setSharingMode('solo')}><Users size={18}/><span><b>Somente eu</b><small>Controle financeiro individual</small></span></button><button className={sharingMode==='shared'?'active':''} onClick={()=>setSharingMode('shared')}><Heart size={18}/><span><b>Compartilhar com cônjuge</b><small>Transforme o espaço em sistema de casal</small></span></button></div>{sharingMode==='shared'&&<div className="partner-invite"><label>E-mail do cônjuge<input type="email" value={partnerEmail} onChange={e=>setPartnerEmail(e.target.value)} placeholder="conjuge@exemplo.com"/></label><button className="primary" onClick={sendInvite}>Enviar convite</button><button className="ghost" onClick={shareWhatsApp}>Compartilhar pelo WhatsApp</button>{inviteStatus&&<div className="invite-status"><Check size={16}/><span>{inviteStatus}<small>O cônjuge deve aceitar o e-mail, criar a própria senha e fazer login.</small></span></div>}</div>}</div>
<div className="couple-edit">{personCard('Rafael','R')}{members.length>1&&<><Heart/>{personCard('Mariana','M')}</>}</div><hr/><div className="setting-row"><span><b>Tema escuro</b><small>Reduza o brilho do aplicativo</small></span><button className={`toggle ${dark?'on':''}`} onClick={()=>setDark(!dark)}><i/></button></div><div className="setting-row"><span><b>Moeda</b><small>Formato usado em todo o app</small></span><select className="settings-select" value={currency} onChange={e=>setCurrency(e.target.value)}><option value="BRL">Real brasileiro (BRL)</option><option value="USD">Dólar (USD)</option><option value="EUR">Euro (EUR)</option></select></div><div className="setting-row"><span><b>Instalar aplicativo</b><small>Acesse o Juntos Finance pela tela inicial</small></span><button className="primary" onClick={install}><Download size={17}/> Instalar</button></div></>}
    {tab==='Preferências'&&<><h3>Preferências</h3><p>Escolha como o aplicativo deve se comportar.</p><div className="setting-row"><span><b>Tema escuro</b><small>Alternar aparência do aplicativo</small></span><button className={`toggle ${dark?'on':''}`} onClick={()=>setDark(!dark)}><i/></button></div><div className="setting-row"><span><b>Moeda principal</b><small>Usada em saldos e relatórios</small></span><select className="settings-select" value={currency} onChange={e=>setCurrency(e.target.value)}><option value="BRL">Real brasileiro (BRL)</option><option value="USD">Dólar (USD)</option><option value="EUR">Euro (EUR)</option></select></div></>}
    {tab==='Notificações'&&<><h3>Notificações</h3><p>Controle os avisos que deseja receber.</p>{([['email','Notificações por e-mail'],['push','Notificações no navegador'],['bills','Lembretes de contas'],['goals','Atualizações de metas']] as const).map(([key,label])=><div className="setting-row" key={key}><span><b>{label}</b><small>Você pode alterar quando quiser</small></span><button className={`toggle ${prefs[key]?'on':''}`} onClick={()=>toggle(key)}><i/></button></div>)}</>}
    {tab==='Privacidade e segurança'&&<><h3>Privacidade e segurança</h3><p>Proteja seus dados financeiros.</p><div className="setting-row"><span><b>Autenticação em duas etapas</b><small>Adiciona uma camada extra de segurança</small></span><button className={`toggle ${prefs.twoFactor?'on':''}`} onClick={()=>toggle('twoFactor')}><i/></button></div><div className="setting-row"><span><b>Alterar senha</b><small>Atualize sua senha de acesso</small></span><button className="ghost" onClick={()=>alert('Um link para alteração de senha foi enviado para seu e-mail.')}>Solicitar link</button></div></>}
    {tab==='Categorias'&&<><h3>Categorias</h3><p>Organize as classificações das movimentações.</p><div className="category-list">{categories.map(x=><div key={x}><span>{x}</span><button onClick={()=>setCategories(categories.filter(c=>c!==x))}><X size={16}/></button></div>)}</div><div className="category-add"><input value={newCategory} onChange={e=>setNewCategory(e.target.value)} placeholder="Nova categoria"/><button className="primary" onClick={()=>{if(newCategory.trim()){setCategories([...categories,newCategory.trim()]);setNewCategory('')}}}><Plus size={16}/> Adicionar</button></div></>}
    {tab==='Dados e exportação'&&<><h3>Dados e exportação</h3><p>Baixe uma cópia das configurações e informações locais.</p><div className="setting-row"><span><b>Exportar meus dados</b><small>Arquivo JSON compatível com backup</small></span><button className="primary" onClick={download}><Download size={17}/> Exportar dados</button></div><div className="setting-row"><span><b>Limpar configurações locais</b><small>Restaura preferências deste navegador</small></span><button className="ghost danger" onClick={()=>{if(confirm('Deseja restaurar as configurações?')){localStorage.removeItem('juntos-settings');location.reload()}}}>Restaurar</button></div></>}
  </section></div></div>
}

function OrganizerPage({title}:{title:string}){
  const key='juntos-organizer-'+title.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,'-');
  const presets:any={};
  const [items,setItems]=useState<any[]>(presets[title]||[]); const [editing,setEditing]=useState<any>(null); const [query,setQuery]=useState('');
  useEffect(()=>{const saved=localStorage.getItem(key);if(saved)try{setItems(JSON.parse(saved))}catch{}},[key]);
  const persist=(next:any[])=>{setItems(next);localStorage.setItem(key,JSON.stringify(next))};
  const openNew=()=>setEditing({id:Date.now(),name:'',value:'',date:'2026-07-19',status:'Planejado',notes:'',isNew:true});
  const save=(e:React.FormEvent)=>{e.preventDefault();const item={...editing,value:Number(String(editing.value).replace(/[.]/g,'').replace(',','.'))};delete item.isNew;persist(editing.isNew?[...items,item]:items.map(x=>x.id===item.id?item:x));setEditing(null);appAction('Alterações salvas com sucesso.')};
  const remove=()=>{if(confirm('Deseja excluir este registro?')){persist(items.filter(x=>x.id!==editing.id));setEditing(null);appAction('Registro excluído.')}};
  const filtered=items.filter(x=>x.name.toLowerCase().includes(query.toLowerCase())); const total=items.reduce((sum,x)=>sum+Number(x.value||0),0);
  return <div className="page-stack organizer-page"><div className="page-heading"><div><p>Organização financeira</p><h1>{title}</h1><span>Cadastre, acompanhe e atualize tudo quando quiser.</span></div><button className="primary" onClick={openNew}><Plus size={17}/> Novo registro</button></div><div className="metrics-grid compact"><MetricCard label="Total planejado" value={brl(total)} detail={`${items.length} registros`} icon={WalletCards} tone="purple"/><MetricCard label="Pendentes" value={String(items.filter(x=>x.status==='Pendente').length)} detail="Precisam de atenção" icon={CalendarDays} tone="warning"/><MetricCard label="Concluídos" value={String(items.filter(x=>x.status==='Concluído').length)} detail="Neste período" icon={Check} tone="positive"/></div><section className="card organizer-list"><label className="search"><Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={`Buscar em ${title.toLowerCase()}...`}/></label>{filtered.length?filtered.map(x=><button className="organizer-row" key={x.id} onClick={()=>setEditing({...x})}><span className="organizer-row-icon"><ReceiptText size={17}/></span><span><b>{x.name}</b><small>{x.notes||'Sem observações'}</small></span><time>{new Date(x.date+'T12:00:00').toLocaleDateString('pt-BR')}</time><i>{x.status}</i><strong>{brl(Number(x.value))}</strong><ChevronRight size={17}/></button>):<div className="organizer-empty">Nenhum registro encontrado.</div>}</section>{editing&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEditing(null)}><form className="modal organizer-editor" onSubmit={save}><div className="edit-modal-head"><div><span>{editing.isNew?'NOVO REGISTRO':'EDITAR REGISTRO'}</span><h2>{editing.isNew?`Adicionar em ${title}`:'Atualizar informações'}</h2><p>Todos os campos podem ser alterados depois.</p></div><button type="button" className="icon-button" onClick={()=>setEditing(null)}><X/></button></div><div className="organizer-edit-grid"><label className="field-full">Nome<input value={editing.name} onChange={e=>setEditing({...editing,name:e.target.value})} required placeholder="Digite um nome"/></label><label>Valor (R$)<input value={editing.value} onChange={e=>setEditing({...editing,value:e.target.value.replace(/[^0-9,.]/g,'')})} required inputMode="decimal"/></label><label>Data<input type="date" value={editing.date} onChange={e=>setEditing({...editing,date:e.target.value})} required/></label><label>Status<select value={editing.status} onChange={e=>setEditing({...editing,status:e.target.value})}><option>Planejado</option><option>Pendente</option><option>Em andamento</option><option>Concluído</option><option>Cancelado</option></select></label><label className="field-full">Observações<textarea rows={3} value={editing.notes} onChange={e=>setEditing({...editing,notes:e.target.value})} placeholder="Detalhes opcionais"/></label></div><div className="edit-modal-actions">{!editing.isNew&&<button type="button" className="ghost danger" onClick={remove}>Excluir</button>}<span/><button type="button" className="ghost" onClick={()=>setEditing(null)}>Cancelar</button><button className="primary"><Check size={17}/> Salvar</button></div></form></div>}</div>
}
function Placeholder({title,onGo}:{title:string,onGo:()=>void}){return <div className="empty-page"><div className="empty-illustration"><Heart/><Sparkles/></div><p>Juntos Finance</p><h1>{title}</h1><span>Este espaço já faz parte da experiência e está pronto para receber seus próximos dados.</span><button className="primary" onClick={onGo}>Voltar ao dashboard</button></div>}

function TransactionModal({close,success,people,isCouple}:any){
  const [type,setType]=useState('Despesa');
  const [form,setForm]=useState({description:'',value:'',date:'2026-07-19',category:'',person:'Rafael',account:'',payment:'',card:'Nenhum',split:'Compartilhada',notes:'',recurring:false});
  const set=(key:string,value:any)=>setForm({...form,[key]:value});
  const categories=['Salário','Alimentação','Mercado','Restaurante','Delivery','Transporte','Combustível','Aluguel','Condomínio','Internet','Luz','Água','Telefone','Saúde','Educação','Filhos','Viagens','Lazer','Compras','Assinaturas','Investimentos','Dívidas','Seguros','Impostos','Outros'];
  const submit=(e:any)=>{e.preventDefault();if(!form.description||!form.value||!form.category||!form.account||!form.payment)return;const parsed=Number(form.value.replace(/[.]/g,'').replace(',','.'));success({...form,title:form.description,value:parsed,type:type==='Receita'?'in':'out',icon:type==='Receita'?'↗':'−'});close()};
  return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&close()}><form className="modal transaction-modal" onSubmit={submit}>
    <div className="transaction-modal-head"><div><h2>Nova transação</h2><p>Registre suas receitas, despesas ou transferências.</p></div><button type="button" onClick={close} aria-label="Fechar"><X size={19}/></button></div>
    <div className="type-switch transaction-types">{['Receita','Despesa','Transferência'].map(x=><button type="button" className={type===x?'active':''} onClick={()=>setType(x)} key={x}>{x}</button>)}</div>
    <div className="transaction-form">
      <label className="field-full">Descrição<input value={form.description} onChange={e=>set('description',e.target.value)} placeholder="Ex: Mercado do mês" required/></label>
      <label>Valor (R$)<input value={form.value} onChange={e=>set('value',e.target.value.replace(/[^0-9,.]/g,''))} placeholder="0,00" inputMode="decimal" required/></label>
      <label>Data<input type="date" value={form.date} onChange={e=>set('date',e.target.value)} required/></label>
      <label>Categoria<select value={form.category} onChange={e=>set('category',e.target.value)} required><option value="">Selecione</option>{categories.map(x=><option key={x}>{x}</option>)}</select></label>
      <label>Pessoa<select value={form.person} onChange={e=>set('person',e.target.value)}><option value="Rafael">{people.Rafael.name.split(' ')[0]||'Você'}</option>{isCouple&&<><option value="Mariana">{people.Mariana.name.split(' ')[0]||'Cônjuge'}</option><option>Casal</option></>}</select></label>
      <label>Conta<select value={form.account} onChange={e=>set('account',e.target.value)} required><option value="">Selecione</option><option value="Conta Rafael">Minha conta</option>{isCouple&&<><option value="Conta Mariana">Conta do cônjuge</option><option>Conta do casal</option></>}<option>Carteira</option></select></label>
      <label>Forma de pagamento<select value={form.payment} onChange={e=>set('payment',e.target.value)} required><option value="">Selecione</option>{['Pix','Débito','Crédito','Dinheiro','Boleto','Transferência'].map(x=><option key={x}>{x}</option>)}</select></label>
      <label>Cartão (opcional)<select value={form.card} onChange={e=>set('card',e.target.value)}><option>Nenhum</option><option>Nubank final 4821</option><option>Inter final 1038</option></select></label>
      <label>Divisão<select value={form.split} onChange={e=>set('split',e.target.value)}><option>Individual</option>{isCouple&&<><option>Compartilhada</option><option>50% para cada</option></>}</select></label>
      <label className="field-full">Observação<textarea value={form.notes} onChange={e=>set('notes',e.target.value)} placeholder="Detalhes opcionais" rows={3}/></label>
      <div className="recurring-row field-full"><span><b>Transação recorrente</b><small>Repetir automaticamente todo mês</small></span><button type="button" className={`toggle ${form.recurring?'on':''}`} onClick={()=>set('recurring',!form.recurring)}><i/></button></div>
    </div>
    <div className="transaction-modal-actions"><button type="button" className="ghost" onClick={close}>Cancelar</button><button className="primary">Salvar transação</button></div>
  </form></div>
}

function FinanceApp(){
  const {user,workspace,members,signOut}=useAuth();
  const isCouple=members.length>1;
  const loggedName=(members.find(m=>m.user_id===user?.id)?.profiles?.full_name||user?.user_metadata?.full_name||'') as string;
  const [active,setActive]=useState("Dashboard"); const [mobileMenu,setMobileMenu]=useState(false); const [modal,setModal]=useState(false); const [toast,setToast]=useState(false); const [hidden,setHidden]=useState(false); const [dark,setDark]=useState(false);
  const [storageReady,setStorageReady]=useState(false);
  const [actionToast,setActionToast]=useState('');
  const [people,setPeople]=useState({Rafael:{name:'',email:''},Mariana:{name:'',email:''}});
  const [balances,setBalances]=useState({couple:0,rafael:0,mariana:0,investments:0});
  const [notificationsOpen,setNotificationsOpen]=useState(false); const [profileOpen,setProfileOpen]=useState(false);
  const [profile,setProfile]=useState({name:"",role:"Administrador"});
  const [spaceOpen,setSpaceOpen]=useState(false); const [space,setSpace]=useState({name:'',description:'Nosso espaço financeiro'});
  const [notifications,setNotifications]=useState<any[]>([]);
  useEffect(()=>{if(localStorage.getItem(ZERO_DATA_VERSION_KEY)!==ZERO_DATA_VERSION){Object.keys(localStorage).forEach(key=>{if(key.startsWith('juntos-'))localStorage.removeItem(key)});localStorage.setItem(ZERO_DATA_VERSION_KEY,ZERO_DATA_VERSION)}setStorageReady(true)},[]);
  useEffect(()=>{document.documentElement.dataset.theme=dark?'dark':'light'},[dark]);
  useEffect(()=>{if('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').catch(()=>undefined)},[]);
  useEffect(()=>{const saved=localStorage.getItem('juntos-profile');if(saved)try{setProfile(JSON.parse(saved))}catch{};const savedSpace=localStorage.getItem('juntos-space');if(savedSpace)try{setSpace(JSON.parse(savedSpace))}catch{}},[]);
  useEffect(()=>{const saved=localStorage.getItem('juntos-settings');if(saved)try{const data=JSON.parse(saved);if(data.people)setPeople(data.people)}catch{}},[]);
  useEffect(()=>{const saved=localStorage.getItem('juntos-balances');if(saved)try{setBalances({...balances,...JSON.parse(saved)})}catch{}},[]);
  useEffect(()=>{const handler=(event:Event)=>{const detail=(event as CustomEvent<string|{page:string}>).detail;if(typeof detail==='string'){setActionToast(detail);setToast(true);setTimeout(()=>setToast(false),2600)}else if(detail?.page){setActive(detail.page);window.scrollTo({top:0,behavior:'smooth'})}};window.addEventListener('juntos-action',handler);return()=>window.removeEventListener('juntos-action',handler)},[]);
  const saveProfile=(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();localStorage.setItem('juntos-profile',JSON.stringify(profile));const current=JSON.parse(localStorage.getItem('juntos-settings')||'{}');localStorage.setItem('juntos-settings',JSON.stringify({...current,people}));setProfileOpen(false);setToast(true);setTimeout(()=>setToast(false),3000)};
  const saveTransaction=(data:any)=>{const saved=localStorage.getItem('juntos-transactions');const current=saved?JSON.parse(saved):transactions;const date=new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(data.date+'T12:00:00')).replace('.','');const next=[{id:Date.now(),title:data.title,category:data.category,person:data.person,account:data.account,payment:data.payment,card:data.card,date,dateInput:data.date,value:data.value,type:data.type,icon:data.icon},...current];localStorage.setItem('juntos-transactions',JSON.stringify(next));const accountKey=data.account==='Conta Rafael'?'rafael':data.account==='Conta Mariana'?'mariana':data.account==='Conta do casal'?'couple':null;if(accountKey){setBalances(previous=>{const updated={...previous,[accountKey]:Math.max(0,Number(previous[accountKey as keyof typeof previous]||0)+(data.type==='in'?data.value:-data.value))};localStorage.setItem('juntos-balances',JSON.stringify(updated));return updated})}window.dispatchEvent(new Event('juntos-transactions-updated'));setActionToast(data.category==='Salário'&&data.type==='in'?'Salário adicionado ao seu saldo!':'Transação adicionada com sucesso!');setToast(true);setTimeout(()=>setToast(false),3000)};
  const unread=notifications.filter(n=>!n.read).length;
  const content=useMemo(()=>{const p:any={Dashboard:<Dashboard onNew={()=>setModal(true)} onAi={()=>setActive('IA Conselheira')} hidden={hidden} setHidden={setHidden} people={people} balances={balances} currentName={loggedName} isCouple={isCouple}/>,"Transações":<TransactionsPage onNew={()=>setModal(true)} people={people} isCouple={isCouple}/>,"Orçamentos":<BudgetsPage/>,Contas:<AccountsPage people={people} setPeople={setPeople} balances={balances} setBalances={setBalances}/>,"Cartões":<CardsPage people={people}/>,"Calendário":<CalendarPage people={people}/>,Metas:<GoalsPage/>,Assinaturas:<SubscriptionsPage/>,"Despesas fixas":<OrganizerPage title="Despesas fixas"/>,"App de compras":<OrganizerPage title="App de compras"/>,"Empréstimos":<OrganizerPage title="Empréstimos"/>,"Cuidados pessoais":<OrganizerPage title="Cuidados pessoais"/>,"Relatórios":<ReportsPage people={people}/>,"IA Conselheira":<AiPage people={people}/>,"Configurações":<SettingsPage dark={dark} setDark={setDark} people={people} setPeople={setPeople}/>};return p[active]||<Placeholder title={active} onGo={()=>setActive('Dashboard')}/>},[active,hidden,dark,people,balances,isCouple]);
  const navigate=(x:string)=>{setActive(x);setMobileMenu(false);window.scrollTo({top:0,behavior:'smooth'})};
  if(!storageReady)return <div className="app-shell"><div className="main-shell"><main /></div></div>;
  return <div className="app-shell">
    <aside className={`sidebar ${mobileMenu?'open':''}`}><div className="sidebar-top"><Logo/><button className="mobile-close icon-button" onClick={()=>setMobileMenu(false)}><X/></button></div><nav><span>MENU PRINCIPAL</span>{menu.map(([label,Icon])=><button key={label} onClick={()=>navigate(label)} className={active===label?'active':''}><Icon size={18}/><span>{label}</span>{label==='IA Conselheira'&&<i>Novo</i>}</button>)}</nav><div className="sidebar-bottom"><button onClick={()=>navigate('Configurações')} className={active==='Configurações'?'active':''}><Settings size={18}/>Configurações</button><div className="month-progress"><span>Orçamento do mês<b>0%</b></span><div><i style={{width:'0%'}}/></div><small>Nenhum orçamento cadastrado</small></div></div></aside>
    <CloudSync/><div className="main-shell"><header className="topbar"><button className="mobile-menu icon-button" onClick={()=>setMobileMenu(true)}><Menu/></button><div className="mobile-logo"><Logo/></div><div className="topbar-spacer"/><button className="icon-button" onClick={()=>setDark(!dark)} aria-label="Alternar tema">{dark?<Sun/>:<Moon/>}</button><div className="header-menu-wrap"><button className="notification icon-button" onClick={()=>{setNotificationsOpen(!notificationsOpen);setProfileOpen(false)}} aria-label="Abrir notificações"><Bell/>{unread>0&&<i>{unread}</i>}</button>{notificationsOpen&&<div className="header-popover notification-panel"><div className="notification-panel-head"><b>Notificações</b><button onClick={()=>setNotifications(n=>n.map(x=>({...x,read:true})))}><Check size={15}/> Marcar lidas</button></div><div className="notification-scroll">{notifications.length?notifications.map(n=><button className={`notification-item ${n.read?'read':''}`} key={n.id} onClick={()=>setNotifications(list=>list.map(x=>x.id===n.id?{...x,read:true}:x))}><i/><span><b>{n.title}</b><small>{n.text}</small><time>{n.time}</time></span></button>):<p className="popover-empty">Nenhuma notificação.</p>}</div></div>}</div><div className="header-menu-wrap"><button className="top-profile" onClick={()=>{setProfileOpen(!profileOpen);setNotificationsOpen(false)}}><Avatar who="R" small label={people.Rafael.name}/><span><b>{loggedName?.split(' ')[0]||people.Rafael.name.split(' ')[0]}</b><small>{workspace?.role==='owner'?'Administrador':workspace?.role==='member'?'Membro':profile.role}</small></span><ChevronDown size={15}/></button>{profileOpen&&<form className="header-popover profile-popover" onSubmit={saveProfile}><h3>Editar perfil</h3><label>Nome<input value={people.Rafael.name} onChange={e=>setPeople({...people,Rafael:{...people.Rafael,name:e.target.value}})} required/></label><label>Função<select value={profile.role} onChange={e=>setProfile({...profile,role:e.target.value})}><option>Administrador</option><option>Membro</option><option>Visualizador</option></select></label><button className="primary">Salvar alterações</button>{user&&<button type="button" className="ghost danger" onClick={signOut}>Sair da conta</button>}</form>}</div></header><main>{content}</main></div>
    <nav className="bottom-nav">{[["Dashboard",Home],["Transações",ReceiptText],["plus",Plus],["Metas",Target],["IA Conselheira",Sparkles]].map(([label,Icon]:any)=><button key={label} className={label==='plus'?'fab':active===label?'active':''} onClick={()=>label==='plus'?setModal(true):navigate(label)}><Icon/>{label!=='plus'&&<span>{label==='IA Conselheira'?'IA':label}</span>}</button>)}</nav>
    {modal&&<TransactionModal people={people} isCouple={isCouple} close={()=>setModal(false)} success={saveTransaction}/>}{toast&&<div className="toast"><Check/> {actionToast||'Alterações salvas com sucesso!'}</div>}
  </div>
}

export default function HomePage(){return <AuthGate><FinanceApp/></AuthGate>}
